  'Marketing Research',
  'Marketing Research',
  'A world-class version needs deeper treatment of mixed-method design, measurement validity, data quality, experiments and causal evidence, segmentation analytics, digital behavioral data, privacy, bias, responsible insights, and executive storytelling. The resulting syllabus covers core topics while expanding them into a decision-oriented, analytics-aware research course.',
  $mkrsjson${"slug": "marketing-research", "title": "Marketing Research", "description": "A world-class version needs deeper treatment of mixed-method design, measurement validity, data quality, experiments and causal evidence, segmentation analytics, digital behavioral data, privacy, bias, responsible insights, and executive storytelling. The resulting syllabus covers core topics while expanding them into a decision-oriented, analytics-aware research course.", "topics": [{"id": "41c4f666-4e39-44ca-932d-eb12d496ec8c", "type": "topic", "title": "Marketing Research, Insight Strategy, and Managerial Decision-Making", "description": "Frame marketing research as the disciplined process of reducing uncertainty for customer, market, brand, product, pricing, channel, and communication decisions.", "children": [{"id": "04fd8510-f93b-4bb6-b3a7-e24d26e2fca3", "type": "subtopic", "title": "What Marketing Research Is For", "children": [{"id": "7d0df1c7-04a0-4c30-8be0-c6a6b2e8c54c", "type": "concept", "title": "Decision uncertainty, customer insight, market opportunity, risk reduction, and evidence-based strategy"}, {"id": "cb55aad2-846c-49fc-8ab5-6df2ec902f6f", "type": "concept", "title": "Customer, competitor, brand, product, price, channel, communication, and experience decisions"}, {"id": "01846e87-b328-4009-adb2-3af901003562", "type": "concept", "title": "Difference between data, findings, insights, implications, and recommendations"}], "description": "Marketing research exists to improve decisions, not merely to collect opinions or produce reports."}, {"id": "1f392d8d-a167-4e81-a42c-2fef0cbf587b", "type": "subtopic", "title": "The Insight Function", "children": [{"id": "230060dd-8c25-4994-8319-dba7be7a8fc0", "type": "concept", "title": "Client-side insights, agency research, UX research, analytics teams, marketing science, and customer experience"}, {"id": "2d8666e9-448d-4322-816c-db940d3aa23e", "type": "concept", "title": "Stakeholders, briefs, budgets, timelines, vendors, panels, and research operations"}, {"id": "c0a5089e-0bd7-4ded-a482-9bc4749fb86b", "type": "concept", "title": "How insights influence strategy, design, campaigns, and investment decisions"}], "description": "Students learn how research teams operate inside firms, agencies, consultancies, startups, and product organizations."}, {"id": "bbf02f11-350f-4245-8db1-569a215a39f1", "type": "subtopic", "title": "Research Quality and Decision Value", "children": [{"id": "3d4b7ba4-09bd-4741-90e0-9e58258b20ba", "type": "concept", "title": "Validity, reliability, representativeness, transparency, bias, triangulation, and reproducibility"}, {"id": "ad5efe31-6ba5-4831-8b73-2ad145cfc7a2", "type": "concept", "title": "Decision value, opportunity cost, research risk, and speed versus rigor tradeoffs"}, {"id": "8fd7c738-88f9-4c8e-a831-79aa24ca0c12", "type": "concept", "title": "When not to research and when existing evidence is enough"}], "description": "A world-class course teaches students to judge research by usefulness, credibility, ethics, and actionability."}]}, {"id": "28ed90d3-a1c5-4727-9eb4-ca4c07869679", "type": "topic", "title": "Problem Definition, Research Questions, and Decision Context", "description": "Translate vague business symptoms into decision-ready research problems, hypotheses, and actionable learning objectives.", "children": [{"id": "2d27b2af-f4f1-4bbf-9dd9-aa3f2e0b823c", "type": "subtopic", "title": "From Business Symptom to Research Problem", "children": [{"id": "ab7a008c-8413-42fa-bbdc-5d602b6984bf", "type": "concept", "title": "Symptoms versus causes, management decision problem, marketing research problem, and information gaps"}, {"id": "9fd9f123-9fa9-42fe-bdd7-5e84d492f4db", "type": "concept", "title": "Stakeholder interviews, background analysis, assumptions, constraints, and decision timeline"}, {"id": "c0083a20-1523-443e-b98a-59cf5cb883ed", "type": "concept", "title": "Problem statements, objectives, hypotheses, and success criteria"}], "description": "This subtopic trains students to resist solving the wrong problem beautifully."}, {"id": "1575cba5-5337-46e3-91f7-86ea41b997db", "type": "subtopic", "title": "Research Questions and Learning Objectives", "children": [{"id": "2671c310-fa0b-468f-b35e-dbe040a0b5b9", "type": "concept", "title": "Exploratory, descriptive, diagnostic, predictive, and causal questions"}, {"id": "472ea99f-78fb-4f68-9108-1fcdc2cef408", "type": "concept", "title": "Primary and secondary questions, hypotheses, constructs, variables, and expected use of findings"}, {"id": "0c6e1e1c-e696-4bb6-bc94-0b27261435fb", "type": "concept", "title": "Research briefs, scope, deliverables, and decision rules"}], "description": "Good research questions define what must be learned before a decision can be made."}, {"id": "b34cb679-dcb4-4c3e-bf3a-0b543dbd9f0a", "type": "subtopic", "title": "Decision Context and Stakeholder Alignment", "children": [{"id": "bebca43a-85ab-4b64-b5b4-62f0a83e991a", "type": "concept", "title": "Decision owner, user of research, budget, risk tolerance, market context, and competitive pressure"}, {"id": "15e7c30c-e1e4-4e64-91d9-cdf28599093a", "type": "concept", "title": "Pre-read alignment, assumption mapping, and project kickoff"}, {"id": "330bf677-a585-4cf4-b660-e14b70fb86d0", "type": "concept", "title": "Avoiding scope creep and post-hoc reinterpretation"}], "description": "Research becomes more valuable when stakeholders agree on the decision, audience, and action threshold."}]}, {"id": "ff79b6e0-fccc-40b1-8afc-6f18e61a6b03", "type": "topic", "title": "Research Design, Mixed Methods, and Evidence Planning", "description": "Choose exploratory, descriptive, causal, qualitative, quantitative, and mixed-method designs that fit the business decision.", "children": [{"id": "d4005ba1-6c97-463a-b3e5-fabc00262bae", "type": "subtopic", "title": "Exploratory, Descriptive, and Causal Designs", "children": [{"id": "6a3dc280-8f63-445f-a577-3e1e283f3b0e", "type": "concept", "title": "Exploratory discovery, descriptive measurement, causal testing, tracking, and diagnostic research"}, {"id": "5d4b3ece-2bca-4976-9f70-1a196eac9b93", "type": "concept", "title": "Qualitative, quantitative, observational, experimental, and mixed-method designs"}, {"id": "b6fdc6cf-e629-4043-bb83-8876f02ea73d", "type": "concept", "title": "Research design as evidence architecture"}], "description": "Students learn to match method to question instead of defaulting to surveys."}, {"id": "054cb5d2-4ac2-4eaf-9bc8-1c11d674024f", "type": "subtopic", "title": "Mixed-Methods Sequencing", "children": [{"id": "6b1e90f6-22cc-40f0-807c-57f62d49f885", "type": "concept", "title": "Qual-to-quant, quant-to-qual, triangulation, explanatory design, and iterative design"}, {"id": "32816bc4-b64f-4003-81e0-05041661b7a0", "type": "concept", "title": "Discovery interviews before survey design, segmentation followed by profiling, and experiments after concept screening"}, {"id": "4108c1a9-0a91-4e01-87a6-4bf1d1fb4aad", "type": "concept", "title": "Integration of findings across methods"}], "description": "Combining methods works best when each phase has a clear purpose."}, {"id": "b284a4b0-8454-4a5e-acf8-86ebbf5c8808", "type": "subtopic", "title": "Evidence Plan and Research Roadmap", "children": [{"id": "139cf464-a577-4b21-89d5-85e3a1fcea00", "type": "concept", "title": "Research matrix, data sources, recruitment plan, timeline, budget, quality checks, and analysis plan"}, {"id": "1bf9c984-6a63-4458-902d-184fac6aedf8", "type": "concept", "title": "Minimum viable research versus comprehensive programs"}, {"id": "704ad3d3-938b-4a2a-9539-125eacaa40c7", "type": "concept", "title": "Tradeoffs among rigor, speed, cost, and confidence"}], "description": "An evidence plan links method, sample, instrument, analysis, and deliverable to the decision."}]}, {"id": "31add8fb-2fd1-4d85-8206-02f79bc7673a", "type": "topic", "title": "Secondary Data, Market Intelligence, and Digital Trace Data", "description": "Use existing data responsibly before commissioning primary research, including market reports, census data, search data, CRM data, and platform analytics.", "children": [{"id": "46e93039-cfac-4494-9245-1e1d77c1dc8c", "type": "subtopic", "title": "Secondary Data Audit", "children": [{"id": "ba696ffc-6e1a-4caf-9bd4-f8ccc1b25dfe", "type": "concept", "title": "Internal records, CRM, sales data, web analytics, syndicated reports, government data, and competitor materials"}, {"id": "742e133b-3d75-4e09-921e-b172d8ac6bf7", "type": "concept", "title": "Source credibility, recency, coverage, definitions, and comparability"}, {"id": "265eee80-3045-48a2-8d38-d4c313813f20", "type": "concept", "title": "Desk research workflow and citation discipline"}], "description": "Secondary research prevents wasted effort and helps students understand market context before primary research."}, {"id": "82aa9afe-d2e2-4bfb-8b40-ab9fb50608d2", "type": "subtopic", "title": "Market and Competitive Intelligence", "children": [{"id": "81640eac-20d2-4c4f-bc7c-0c017cc47e73", "type": "concept", "title": "Market size, growth, share, category structure, competitor positioning, pricing, channels, and substitutes"}, {"id": "60f0f11a-009e-436f-9cf5-1243ba749602", "type": "concept", "title": "PESTEL, Porter's forces, category entry points, and trend analysis"}, {"id": "9f6bb09b-272e-4e52-be8d-17853a87178c", "type": "concept", "title": "Use and limits of public data and industry reports"}], "description": "Students learn to map markets, categories, competitors, and demand signals."}, {"id": "ca318737-5ab2-4f97-ba16-2dcef088f058", "type": "subtopic", "title": "Big Data and Behavioral Traces", "children": [{"id": "54bbaa42-223e-473d-8890-a2612fef9c47", "type": "concept", "title": "Search trends, social data, clickstream, transaction data, loyalty data, reviews, and app events"}, {"id": "76bb0d96-7392-4a32-840b-7aa9ea7219c5", "type": "concept", "title": "Data exhaust, selection bias, measurement gaps, and platform changes"}, {"id": "36866f64-a170-449a-9313-60135d75c3ef", "type": "concept", "title": "What behavior data can and cannot say about motives"}], "description": "Digital and operational data can reveal behavior at scale, but it requires careful interpretation."}]}, {"id": "c621c00e-4c5e-4285-b39e-dfeefbd5c632", "type": "topic", "title": "Qualitative Research: Interviews, Focus Groups, Ethnography, and Customer Discovery", "description": "Learn how qualitative research reveals motives, language, context, unmet needs, barriers, and opportunity spaces.", "children": [{"id": "1d32caf8-b7d5-4e16-82be-4b5df84c44fd", "type": "subtopic", "title": "Depth Interviews and Customer Discovery", "children": [{"id": "62aaacc2-ccd1-43fb-88e3-3a431744f82e", "type": "concept", "title": "Discussion guides, probes, laddering, jobs to be done, pain points, and unmet needs"}, {"id": "ceff3615-b794-4aa4-8529-6fcace9f29bd", "type": "concept", "title": "Recruiting, moderation, rapport, active listening, and note-taking"}, {"id": "d7e05d7a-bee2-474f-a7d2-71db2725c832", "type": "concept", "title": "Synthesis from transcripts, quotes, patterns, and contradictions"}], "description": "Interviews help researchers understand language, motivations, needs, barriers, and decision journeys."}, {"id": "6aa94060-240f-406a-9b26-275adfd92093", "type": "subtopic", "title": "Focus Groups and Co-Creation", "children": [{"id": "136862c4-0173-4d71-92ae-579b39e183db", "type": "concept", "title": "Focus groups, mini-groups, online communities, workshops, concept boards, and stimulus testing"}, {"id": "703e4580-78d1-49d8-917d-f234325e2b66", "type": "concept", "title": "Group dynamics, dominance, conformity, moderation, and projective techniques"}, {"id": "0261b81f-2cc7-4d18-938d-cb093df68a07", "type": "concept", "title": "When focus groups are useful and when they mislead"}], "description": "Group methods can reveal social meaning, concept reactions, vocabulary, and creative possibilities when used carefully."}, {"id": "73246740-26f9-4bbd-97b6-d19d372c932f", "type": "subtopic", "title": "Ethnography and Contextual Observation", "children": [{"id": "1eb3a035-dd80-4650-9c31-4d921b9cd435", "type": "concept", "title": "Shop-alongs, diary studies, contextual inquiry, mobile ethnography, user observation, and service safaris"}, {"id": "1178f86b-8a53-4f12-8615-db3baefbd0a1", "type": "concept", "title": "Environment, routines, workarounds, artifacts, and embodied behavior"}, {"id": "38eb334a-6632-4d58-a69f-b384abc32a8d", "type": "concept", "title": "Ethics of observation and interpretation"}], "description": "Observational research helps students see the gap between what people say and what people do."}]}, {"id": "db31345d-7b1e-4233-a169-1b3dc68fc22d", "type": "topic", "title": "Survey Design, Questionnaire Craft, and Measurement Validity", "description": "Build surveys that measure the right constructs with clear wording, valid scales, and minimized response bias.", "children": [{"id": "13a53266-627e-4bd4-adcf-14898e749f54", "type": "subtopic", "title": "Constructs and Measures", "children": [{"id": "2d524bdf-e920-470b-8328-75589fc6446c", "type": "concept", "title": "Constructs, operationalization, indicators, latent variables, and measurement model"}, {"id": "616d374d-5977-4e47-99c1-2f730a0c82c2", "type": "concept", "title": "Awareness, attitudes, preferences, satisfaction, loyalty, intent, usage, and willingness to pay"}, {"id": "c232ad9c-6e72-490d-aa07-887f5fb6bb8e", "type": "concept", "title": "Validity, reliability, sensitivity, and benchmark comparability"}], "description": "Strong surveys begin by defining what needs to be measured before writing questions."}, {"id": "a48e8fbf-e7e9-4fb7-8b03-7be79c6954c2", "type": "subtopic", "title": "Questionnaire Writing", "children": [{"id": "4aac95f8-9633-4374-b955-fa53c3b7ec6c", "type": "concept", "title": "Question order, screening, branching, scale labels, recall periods, neutral wording, and response options"}, {"id": "fc048450-febf-4eca-8ba0-fdd5ac360825", "type": "concept", "title": "Leading, loaded, double-barreled, ambiguous, and socially desirable questions"}, {"id": "2e26d790-4635-49ce-9789-c97880f75971", "type": "concept", "title": "Pretesting, cognitive interviews, and survey pilots"}], "description": "Question wording can quietly determine the quality of the entire study."}, {"id": "abd30276-52c3-4b52-ae03-2adad4b77ecf", "type": "subtopic", "title": "Scale Design and Survey Experience", "children": [{"id": "fdfe966c-64d9-4319-9075-a1b652951970", "type": "concept", "title": "Likert scales, semantic differential scales, ranking, max-diff, constant sum, open text, and matrix questions"}, {"id": "04354b71-efc8-4852-9ab4-1ded44ae9324", "type": "concept", "title": "Mobile-first design, survey fatigue, length, incentives, and accessibility"}, {"id": "b7dc1671-7980-4d14-88a8-80dea198b015", "type": "concept", "title": "Translation, localization, and cross-cultural measurement"}], "description": "Students learn to design surveys respondents can answer accurately and willingly."}]}, {"id": "f37ddd65-d5db-441c-8d49-f021846aac24", "type": "topic", "title": "Sampling, Panels, Fieldwork, and Data Quality", "description": "Design samples and fieldwork protocols that produce credible, transparent, and decision-useful evidence.", "children": [{"id": "a9b51646-760c-42b5-94ee-16743470ccac", "type": "subtopic", "title": "Sampling Logic", "children": [{"id": "c8000b1e-64db-4fe3-ae42-fc54bae9df98", "type": "concept", "title": "Population, sampling frame, census, probability sampling, nonprobability sampling, and sample size"}, {"id": "dc7b2971-1480-4805-9ce1-9df36fadddf1", "type": "concept", "title": "Simple random, stratified, cluster, quota, convenience, snowball, and purposive sampling"}, {"id": "0ed5bf94-c8ce-4749-8671-a2910145242e", "type": "concept", "title": "Margin of error, confidence interval, incidence rate, and feasibility"}], "description": "Sampling determines how confidently findings can speak beyond the people observed."}, {"id": "5afe9352-96b6-4814-8175-1f6f258007ae", "type": "subtopic", "title": "Panels and Fieldwork Operations", "children": [{"id": "bd124008-e770-442a-bd6c-0ef14d6fe186", "type": "concept", "title": "Online panels, customer lists, intercepts, B2B recruiting, hard-to-reach audiences, and incentives"}, {"id": "029b81fd-c5f7-42f5-9309-aaf98aa8e0d0", "type": "concept", "title": "Screeners, quotas, fieldwork monitoring, response rates, and vendor management"}, {"id": "4b590066-5b69-4a66-b77a-d9dc4db0199f", "type": "concept", "title": "Survey launch checklist and fieldwork troubleshooting"}], "description": "Students learn the practical mechanics of recruiting, screening, fielding, and monitoring research."}, {"id": "b0b47a72-a189-41b9-bcd7-a51e885ce588", "type": "subtopic", "title": "Data Quality and Cleaning", "children": [{"id": "01a7cb82-4c58-42b1-ba25-09d7c36d0a9f", "type": "concept", "title": "Speeders, straight-liners, duplicate responses, bot detection, attention checks, open-end quality, and missing data"}, {"id": "af882444-4b0d-41d4-9bac-58edfa12e84f", "type": "concept", "title": "Weighting, outlier handling, data cleaning logs, and transparency"}, {"id": "4a8d198a-6607-4fd0-af19-8d9f633e94a2", "type": "concept", "title": "Bias from poor recruitment, bad instruments, and careless fielding"}], "description": "Good analysis starts with knowing which responses deserve trust."}]}, {"id": "b1e21dd7-e71c-4d6b-af18-ceab7fe54d82", "type": "topic", "title": "Experiments, A/B Testing, Concept Testing, and Causal Evidence", "description": "Use experimental logic to evaluate claims about products, messages, prices, user experiences, and campaigns.", "children": [{"id": "88abb65a-73da-4c19-872e-ee29b61774ed", "type": "subtopic", "title": "Experimental Logic", "children": [{"id": "7f184947-c18b-47dd-8fa6-e3ad32e8f57d", "type": "concept", "title": "Treatment, control, random assignment, manipulation, dependent variable, confounds, and internal validity"}, {"id": "77f39642-a9af-4530-89ee-f195bd843b8b", "type": "concept", "title": "Laboratory, field, online, and natural experiments"}, {"id": "0eda1fc3-6737-4810-9949-b3550fffcc83", "type": "concept", "title": "Effect size, statistical power, and practical significance"}], "description": "Experiments help marketers learn what causes outcomes rather than merely what correlates with them."}, {"id": "2f791609-1c70-434c-a47e-bdfbb6ca42b9", "type": "subtopic", "title": "A/B Testing and Digital Experiments", "children": [{"id": "496de150-fe6b-4698-8c1c-db57cac96c6a", "type": "concept", "title": "Hypothesis, variants, traffic allocation, guardrail metrics, conversion metrics, and stopping rules"}, {"id": "343c5392-06a6-4542-9793-8a5201eebc82", "type": "concept", "title": "Sample ratio mismatch, novelty effects, peeking, multiple comparisons, and interference"}, {"id": "9fc515d0-1353-42d1-84fd-405dda58bf84", "type": "concept", "title": "Experiment documentation and learning repositories"}], "description": "A/B testing brings experimental thinking into websites, apps, emails, ads, and funnels."}, {"id": "529abfbc-24e6-4725-88f4-42899d20c6c9", "type": "subtopic", "title": "Concept, Product, and Message Testing", "children": [{"id": "aa3ee6b7-342d-48f7-928e-79182923e4b5", "type": "concept", "title": "Concept tests, monadic designs, sequential monadic designs, message tests, package tests, and ad copy tests"}, {"id": "f918868d-86ae-46d9-b63b-145a8c1b26ef", "type": "concept", "title": "Test stimuli, benchmarks, normative databases, and decision thresholds"}, {"id": "993ef130-b564-4f7e-bcfc-2846486cd2aa", "type": "concept", "title": "Connecting test results to launch, iteration, or kill decisions"}], "description": "Students apply causal and quasi-causal designs to marketing decisions."}]}, {"id": "e21cd4d1-92c6-4082-a149-4b7d7d6a987e", "type": "topic", "title": "Quantitative Analysis: Descriptives, Inference, Regression, and Modeling Basics", "description": "Analyze research data with statistical discipline, connecting findings to uncertainty, effect size, and managerial meaning.", "children": [{"id": "08f9ba04-aa70-46e6-9046-6b6b78af829e", "type": "subtopic", "title": "Descriptive Analysis and Cross-Tabs", "children": [{"id": "bacfec4a-1ccd-440e-a948-d62dd242626c", "type": "concept", "title": "Frequencies, means, medians, distributions, cross-tabs, top-box scores, nets, and subgroup comparisons"}, {"id": "86d75eb1-c975-44cf-ade5-3dbe0bd3e653", "type": "concept", "title": "Weighting, filters, missing data, and base sizes"}, {"id": "81823db1-d90c-4fca-9ccb-299d4937e6a2", "type": "concept", "title": "Avoiding misleading percentages and overclaiming small cells"}], "description": "Descriptive analysis turns raw responses into readable patterns and initial implications."}, {"id": "ddea99ec-c3b6-4cfa-bd36-525dbd50fd9f", "type": "subtopic", "title": "Statistical Inference", "children": [{"id": "ede6e9b1-bb6c-47e9-8875-f1de92af893e", "type": "concept", "title": "Confidence intervals, hypothesis tests, p-values, effect sizes, chi-square, t-tests, ANOVA, and nonparametric checks"}, {"id": "f52469ae-fe53-413e-9ca1-4d4f498c232c", "type": "concept", "title": "Statistical significance versus managerial significance"}, {"id": "cdc501af-cc9d-4794-ab0b-c93185022866", "type": "concept", "title": "Multiple testing and false certainty"}], "description": "Students learn how to distinguish signal from noise without turning statistics into decoration."}, {"id": "2c26529d-738d-4ae4-93e2-d97b77ec4a1a", "type": "subtopic", "title": "Regression and Predictive Modeling Basics", "children": [{"id": "0280e3ef-39c0-48c6-ad0e-acc59566721b", "type": "concept", "title": "Correlation, regression, logistic regression, classification, validation, overfitting, and feature selection"}, {"id": "dc702322-3134-4b68-9658-d780ccf02fcc", "type": "concept", "title": "Drivers of satisfaction, purchase intent, churn, and response"}, {"id": "287e0c99-754b-48f5-a55a-0d2ceeba48d3", "type": "concept", "title": "Model interpretation for nontechnical decision-makers"}], "description": "Modeling helps explain drivers and predict outcomes, but only if assumptions and limitations are visible."}]}, {"id": "602dd5b4-02ce-45c5-b732-81f1a6ab3914", "type": "topic", "title": "Segmentation, Targeting Insights, Personas, and Customer Heterogeneity", "description": "Turn research data into meaningful customer groups, needs states, jobs to be done, and targeting implications.", "children": [{"id": "302a8b4a-260a-4fad-bdd8-e9e20b1b93d4", "type": "subtopic", "title": "Segmentation Strategy", "children": [{"id": "0a498e01-e04b-434a-aeab-673d35b5b600", "type": "concept", "title": "Needs-based, behavioral, psychographic, demographic, firmographic, and value-based segmentation"}, {"id": "c7ff881f-a201-4ecd-8581-26951736320b", "type": "concept", "title": "Actionability, identifiability, accessibility, responsiveness, and profitability"}, {"id": "759f13d1-f8ef-4544-a235-1944b9a0aeb0", "type": "concept", "title": "Segment sizing and prioritization"}], "description": "Segmentation is useful when it changes targeting, positioning, product, or resource allocation decisions."}, {"id": "f051eee9-e21c-4f60-8121-ce33b73ca06b", "type": "subtopic", "title": "Segmentation Methods", "children": [{"id": "dc7d4f60-d32e-424a-af0d-5bd47e179a85", "type": "concept", "title": "Cluster analysis, latent class analysis, factor analysis, decision trees, and rule-based segmentation"}, {"id": "f177d9bc-ce08-484c-a81c-91ff0a9b55ee", "type": "concept", "title": "Variable selection, standardization, number of segments, profiling, and validation"}, {"id": "7f65fe27-6b8d-4b24-9637-9c873155384b", "type": "concept", "title": "Interpreting segments without stereotyping customers"}], "description": "Students learn the analytical approaches behind customer grouping."}, {"id": "85057f17-5370-4c26-b198-5fd3dca09205", "type": "subtopic", "title": "Personas and Jobs to Be Done", "children": [{"id": "7171d567-7442-41b4-abd6-ddc8410d73a6", "type": "concept", "title": "Persona evidence, customer jobs, outcomes, pains, gains, trigger events, and usage occasions"}, {"id": "ebc274f2-fa3c-495c-ab52-c3e52db21a1c", "type": "concept", "title": "Difference between creative persona, evidence-based persona, and stereotype"}, {"id": "ec79dcb0-9420-4830-9330-f4253d151acd", "type": "concept", "title": "Using personas in positioning, messaging, and journey design"}], "description": "Personas and jobs frameworks translate data into empathy and product/communication decisions."}]}, {"id": "38836dc2-17a3-4bf4-abfc-deef32b15d76", "type": "topic", "title": "Brand, Product, Pricing, and Customer Value Research", "description": "Apply research methods to brand equity, product-market fit, willingness to pay, conjoint analysis, satisfaction, loyalty, and customer value.", "children": [{"id": "e50fcd69-1132-463f-bcc6-0bab67c2bc3f", "type": "subtopic", "title": "Brand and Positioning Research", "children": [{"id": "f0341de6-1a41-42fc-9612-a82272273fc1", "type": "concept", "title": "Awareness, recall, recognition, brand associations, equity, consideration, preference, and distinctiveness"}, {"id": "f97bb9f3-ef5a-4f4f-a5fa-b0d938873626", "type": "concept", "title": "Perceptual maps, brand trackers, copy tests, and positioning studies"}, {"id": "6431c75d-94cd-416d-ab3b-250616434cc6", "type": "concept", "title": "Competitive frames of reference and points of difference"}], "description": "Brand research measures what customers know, feel, remember, and associate with a brand."}, {"id": "b4a47d34-f8d9-40fa-b36a-381cdf239fa1", "type": "subtopic", "title": "Product and Innovation Research", "children": [{"id": "677855b3-f676-4b26-a54a-02c74027e035", "type": "concept", "title": "Concept testing, prototype testing, usability feedback, product-market fit, feature prioritization, and needs analysis"}, {"id": "821662df-042f-4f15-847e-d6d55ea33950", "type": "concept", "title": "Kano, max-diff, conjoint, choice modeling, and concept screening"}, {"id": "e1fcdc1e-608c-40e9-a13a-1822178f980a", "type": "concept", "title": "Translating feedback into product requirements"}], "description": "Product research helps teams decide what to build, improve, launch, or stop."}, {"id": "ae9361e4-eb31-4611-b21c-954d150da0b2", "type": "subtopic", "title": "Pricing and Customer Value", "children": [{"id": "2a50bb9b-75b4-4d29-b7b6-0a7334b63af6", "type": "concept", "title": "Van Westendorp, Gabor-Granger, conjoint, price elasticity, reference price, and value drivers"}, {"id": "ddc38146-9a8c-4542-93b4-8157345d190d", "type": "concept", "title": "Customer lifetime value, retention, loyalty, and customer equity"}, {"id": "901a3d0b-779b-4c2e-b3aa-3c9b5d5b88dd", "type": "concept", "title": "Limits of stated willingness to pay"}], "description": "Pricing research estimates willingness to pay and value perception while respecting strategic context."}]}, {"id": "838c3e8c-7f47-496a-a953-4bfdfd216f43", "type": "topic", "title": "Digital, Social, Search, and Behavioral Data Research", "description": "Integrate surveys and qualitative insight with digital behavior, social listening, analytics, attribution, and customer journey evidence.", "children": [{"id": "2e46b9a5-7092-4dad-8125-4f3b0da80fac", "type": "subtopic", "title": "Web and Product Analytics", "children": [{"id": "1c4a775c-975c-4691-b4d7-949c80488ac5", "type": "concept", "title": "GA4, events, funnels, cohorts, attribution, dashboards, tags, and conversion tracking"}, {"id": "371e03f1-e5cd-45eb-9ec1-e00d30f4b224", "type": "concept", "title": "Measurement plans, implementation QA, and channel taxonomy"}, {"id": "49e1bd82-ebc9-491b-b6fa-0ef8a733ae5c", "type": "concept", "title": "Behavioral metrics versus customer insight"}], "description": "Digital analytics provide behavioral evidence about acquisition, engagement, conversion, and retention."}, {"id": "54ca6879-03bc-4b2d-97f9-1c7cc3bb12d4", "type": "subtopic", "title": "Social Listening and Review Mining", "children": [{"id": "d0902cd0-2cb6-41ea-a1cd-7ca3312fd9c9", "type": "concept", "title": "Sentiment analysis, topic modeling, text coding, share of voice, influencer mapping, and review analysis"}, {"id": "b64b59bc-d6aa-4879-a12f-5fd65e4e4a04", "type": "concept", "title": "Sampling bias, sarcasm, bots, platform demographics, and context collapse"}, {"id": "a266670e-f2f3-4595-9c70-6646a607f340", "type": "concept", "title": "Turning unstructured text into research evidence"}], "description": "Social and review data reveal public language, complaints, advocacy, and emerging issues."}, {"id": "a9cb47fd-b5f7-4864-994a-1031555471a9", "type": "subtopic", "title": "Search and Demand Signals", "children": [{"id": "28929000-9d77-4d1c-af73-80ae242fc5a4", "type": "concept", "title": "Google Trends, keyword research, search intent, seasonality, content gaps, and competitive demand"}, {"id": "b9436a25-48ca-4e54-8e8a-362a860f5725", "type": "concept", "title": "Demand sensing, category language, and early trend detection"}, {"id": "f0e88bd9-5d93-4090-8f47-cac0cb71230d", "type": "concept", "title": "Triangulating search with surveys, sales, and qualitative research"}], "description": "Search data can reveal needs, language, timing, and category demand."}]}, {"id": "329169ce-fdff-4909-90cc-20946a21ff93", "type": "topic", "title": "Ethics, Privacy, Bias, Inclusion, and Responsible Insights", "description": "Practice marketing research that respects respondents, protects data, avoids manipulation, and recognizes bias in methods and interpretation.", "children": [{"id": "6b90bc10-950d-4a66-836e-eb60ab264216", "type": "subtopic", "title": "Research Ethics and Respondent Respect", "children": [{"id": "68040e1c-8623-4709-9cac-77afd0616a21", "type": "concept", "title": "Informed consent, voluntary participation, deception, incentives, vulnerable populations, and debriefing"}, {"id": "cc86ee6f-8048-48f1-b9ce-e44692ce29a2", "type": "concept", "title": "Confidentiality, anonymity, respondent burden, and right to withdraw"}, {"id": "15999026-b099-4d49-9018-ef35bdf2b318", "type": "concept", "title": "Professional codes and review practices"}], "description": "Ethical research protects people from harm and treats participation as a relationship of trust."}, {"id": "47b82c3f-48cd-4464-bd51-dd6f58452c9e", "type": "subtopic", "title": "Privacy, Security, and Data Governance", "children": [{"id": "3d5696b5-0ac7-45b4-bd17-4b40b8ede5b5", "type": "concept", "title": "Personally identifiable information, consent, data minimization, retention, access control, and secure transfer"}, {"id": "dfcdbdea-997d-4b71-ad8c-3f4cab7bb521", "type": "concept", "title": "GDPR, CCPA/CPRA awareness, FTC guidance, and platform policy constraints"}, {"id": "81c51f48-5404-4b3e-a9d6-05e82e3d94d1", "type": "concept", "title": "Privacy-by-design and responsible data sharing"}], "description": "Marketing research increasingly depends on customer data, so governance is part of the method."}, {"id": "d3723cc6-7882-4561-bb8b-95b70c02169b", "type": "subtopic", "title": "Bias, Inclusion, and Harm", "children": [{"id": "7ff6bdb3-e5f5-4ddc-a47e-9d38fe5039e3", "type": "concept", "title": "Coverage bias, nonresponse bias, algorithmic bias, stereotype threat, cultural bias, and accessibility"}, {"id": "e11cb508-7623-4194-ab9d-36577c3a7453", "type": "concept", "title": "Inclusive questionnaire design, multilingual research, and representative recruitment"}, {"id": "f7bd2f6b-cd54-43e7-b123-f98f15140698", "type": "concept", "title": "Avoiding manipulative targeting and harmful segmentation"}], "description": "Students learn to identify bias in sampling, measurement, analysis, and recommendations."}]}, {"id": "ea18acf7-9feb-40f5-89c9-d8c27f81b067", "type": "topic", "title": "Insight Reporting, Data Visualization, and Executive Storytelling", "description": "Transform analysis into clear recommendations, dashboards, narratives, and presentations that decision-makers can act on.", "children": [{"id": "deaeeb8a-8879-4241-8436-811c54a417ea", "type": "subtopic", "title": "From Findings to Insights", "children": [{"id": "c577292f-8062-415c-bee0-bc0c7899fb84", "type": "concept", "title": "Finding, implication, recommendation, evidence, confidence, and action"}, {"id": "fb8e1f50-375c-4099-bf5b-199f2119d8aa", "type": "concept", "title": "Insight hierarchy, executive summary, answer-first writing, and decision framing"}, {"id": "7cb0764e-4dbc-42e3-9ff2-0ac3301263c9", "type": "concept", "title": "Separating fact, interpretation, and recommendation"}], "description": "A finding states what happened; an insight explains why it matters and what to do next."}, {"id": "4bd0e634-9ee9-4944-a210-bcb1d688b697", "type": "subtopic", "title": "Visualization and Dashboard Design", "children": [{"id": "d58a83fe-a087-47b6-a0d9-bd17f161d751", "type": "concept", "title": "Charts, tables, cross-tabs, dashboards, scorecards, and data labels"}, {"id": "b2e92b05-4a8c-49ec-84de-ac957a915d1c", "type": "concept", "title": "Base sizes, uncertainty, scale choices, color, annotations, and accessibility"}, {"id": "b1a6916e-cbf1-4916-921f-ebf6fcd51c66", "type": "concept", "title": "Avoiding chartjunk, cherry-picking, and misleading comparisons"}], "description": "Research reporting should make patterns clear without distorting the evidence."}, {"id": "ad3f8493-fdad-40c5-97e7-346656b00b4d", "type": "subtopic", "title": "Presentation and Stakeholder Influence", "children": [{"id": "faf17168-8da6-4e53-b230-7c022bc191a8", "type": "concept", "title": "Storyline, audience analysis, recommendation logic, objections, and next steps"}, {"id": "75e0c804-227a-4ed1-a07f-08617c7f14f6", "type": "concept", "title": "Research readout, workshop, executive deck, and appendix"}, {"id": "bd6ed192-d4eb-476d-9c59-a50aeac43ae7", "type": "concept", "title": "Communicating limitations without weakening credibility"}], "description": "Insights only matter when decision-makers understand, trust, and use them."}]}, {"id": "008c60cc-9f6e-4b86-bf3c-7462b5c29f47", "type": "topic", "title": "Capstone: End-to-End Marketing Research Project", "description": "Synthesize problem definition, design, data collection, analysis, ethics, and presentation in a complete research project.", "children": [{"id": "62e17d7d-7099-48f2-97ed-50d51e20cfe8", "type": "subtopic", "title": "Research Brief and Design", "children": [{"id": "4ad60895-4f90-49da-ae38-62e1fbedc969", "type": "concept", "title": "Problem statement, decision context, learning objectives, hypotheses, method, sample, and timeline"}, {"id": "c9967adc-fcec-4b9f-8e00-c88464a579ba", "type": "concept", "title": "Research brief, stakeholder alignment, and evidence plan"}, {"id": "0e756040-c6ee-42f4-8857-e0477bfc01ee", "type": "concept", "title": "Ethics and privacy review before data collection"}], "description": "The capstone begins with a realistic business decision and a defensible research design."}, {"id": "c78e4baa-b09e-4743-a1f3-afcff88eb892", "type": "subtopic", "title": "Data Collection and Analysis", "children": [{"id": "19d6769d-75b3-4c54-a366-4f7a595a812a", "type": "concept", "title": "Qualitative protocol, survey instrument, sampling plan, fieldwork monitoring, and cleaning"}, {"id": "de755922-ffc1-488d-ac7d-90fba52699de", "type": "concept", "title": "Cross-tabs, statistical tests, regression, segmentation, and qualitative coding"}, {"id": "90b63125-ab59-4f5c-bdd5-65db182d4982", "type": "concept", "title": "Triangulation across primary and secondary evidence"}], "description": "Students carry out the research with enough rigor to make the findings credible."}, {"id": "f777008a-bed2-4107-b3e1-28772d546c3e", "type": "subtopic", "title": "Final Insight Deliverable", "children": [{"id": "ee245d0b-cedc-488f-a18a-524043f8e3ed", "type": "concept", "title": "Executive deck, methodology appendix, dashboard or visuals, and recommendation memo"}, {"id": "1b6c776b-d9b8-41d5-87c0-a278aa877a03", "type": "concept", "title": "Confidence, limitations, risks, and decision implications"}, {"id": "bdb4edf8-914e-4d1a-bc26-07434db6c80d", "type": "concept", "title": "Peer review, presentation, revision, and archive of research assets"}], "description": "The final project should look and feel like work a strong insights team could present to leadership."}]}], "dbBacked": true}$mkrsjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'marketing-research'
);

update public.learning_paths
set
  title = 'Marketing Research',
  goal = 'Marketing Research',
  summary = 'A world-class version needs deeper treatment of mixed-method design, measurement validity, data quality, experiments and causal evidence, segmentation analytics, digital behavioral data, privacy, bias, responsible insights, and executive storytelling. The resulting syllabus covers core topics while expanding them into a decision-oriented, analytics-aware research course.',
  data = $mkrsjson${"slug": "marketing-research", "title": "Marketing Research", "description": "A world-class version needs deeper treatment of mixed-method design, measurement validity, data quality, experiments and causal evidence, segmentation analytics, digital behavioral data, privacy, bias, responsible insights, and executive storytelling. The resulting syllabus covers core topics while expanding them into a decision-oriented, analytics-aware research course.", "topics": [{"id": "41c4f666-4e39-44ca-932d-eb12d496ec8c", "type": "topic", "title": "Marketing Research, Insight Strategy, and Managerial Decision-Making", "description": "Frame marketing research as the disciplined process of reducing uncertainty for customer, market, brand, product, pricing, channel, and communication decisions.", "children": [{"id": "04fd8510-f93b-4bb6-b3a7-e24d26e2fca3", "type": "subtopic", "title": "What Marketing Research Is For", "children": [{"id": "7d0df1c7-04a0-4c30-8be0-c6a6b2e8c54c", "type": "concept", "title": "Decision uncertainty, customer insight, market opportunity, risk reduction, and evidence-based strategy"}, {"id": "cb55aad2-846c-49fc-8ab5-6df2ec902f6f", "type": "concept", "title": "Customer, competitor, brand, product, price, channel, communication, and experience decisions"}, {"id": "01846e87-b328-4009-adb2-3af901003562", "type": "concept", "title": "Difference between data, findings, insights, implications, and recommendations"}], "description": "Marketing research exists to improve decisions, not merely to collect opinions or produce reports."}, {"id": "1f392d8d-a167-4e81-a42c-2fef0cbf587b", "type": "subtopic", "title": "The Insight Function", "children": [{"id": "230060dd-8c25-4994-8319-dba7be7a8fc0", "type": "concept", "title": "Client-side insights, agency research, UX research, analytics teams, marketing science, and customer experience"}, {"id": "2d8666e9-448d-4322-816c-db940d3aa23e", "type": "concept", "title": "Stakeholders, briefs, budgets, timelines, vendors, panels, and research operations"}, {"id": "c0a5089e-0bd7-4ded-a482-9bc4749fb86b", "type": "concept", "title": "How insights influence strategy, design, campaigns, and investment decisions"}], "description": "Students learn how research teams operate inside firms, agencies, consultancies, startups, and product organizations."}, {"id": "bbf02f11-350f-4245-8db1-569a215a39f1", "type": "subtopic", "title": "Research Quality and Decision Value", "children": [{"id": "3d4b7ba4-09bd-4741-90e0-9e58258b20ba", "type": "concept", "title": "Validity, reliability, representativeness, transparency, bias, triangulation, and reproducibility"}, {"id": "ad5efe31-6ba5-4831-8b73-2ad145cfc7a2", "type": "concept", "title": "Decision value, opportunity cost, research risk, and speed versus rigor tradeoffs"}, {"id": "8fd7c738-88f9-4c8e-a831-79aa24ca0c12", "type": "concept", "title": "When not to research and when existing evidence is enough"}], "description": "A world-class course teaches students to judge research by usefulness, credibility, ethics, and actionability."}]}, {"id": "28ed90d3-a1c5-4727-9eb4-ca4c07869679", "type": "topic", "title": "Problem Definition, Research Questions, and Decision Context", "description": "Translate vague business symptoms into decision-ready research problems, hypotheses, and actionable learning objectives.", "children": [{"id": "2d27b2af-f4f1-4bbf-9dd9-aa3f2e0b823c", "type": "subtopic", "title": "From Business Symptom to Research Problem", "children": [{"id": "ab7a008c-8413-42fa-bbdc-5d602b6984bf", "type": "concept", "title": "Symptoms versus causes, management decision problem, marketing research problem, and information gaps"}, {"id": "9fd9f123-9fa9-42fe-bdd7-5e84d492f4db", "type": "concept", "title": "Stakeholder interviews, background analysis, assumptions, constraints, and decision timeline"}, {"id": "c0083a20-1523-443e-b98a-59cf5cb883ed", "type": "concept", "title": "Problem statements, objectives, hypotheses, and success criteria"}], "description": "This subtopic trains students to resist solving the wrong problem beautifully."}, {"id": "1575cba5-5337-46e3-91f7-86ea41b997db", "type": "subtopic", "title": "Research Questions and Learning Objectives", "children": [{"id": "2671c310-fa0b-468f-b35e-dbe040a0b5b9", "type": "concept", "title": "Exploratory, descriptive, diagnostic, predictive, and causal questions"}, {"id": "472ea99f-78fb-4f68-9108-1fcdc2cef408", "type": "concept", "title": "Primary and secondary questions, hypotheses, constructs, variables, and expected use of findings"}, {"id": "0c6e1e1c-e696-4bb6-bc94-0b27261435fb", "type": "concept", "title": "Research briefs, scope, deliverables, and decision rules"}], "description": "Good research questions define what must be learned before a decision can be made."}, {"id": "b34cb679-dcb4-4c3e-bf3a-0b543dbd9f0a", "type": "subtopic", "title": "Decision Context and Stakeholder Alignment", "children": [{"id": "bebca43a-85ab-4b64-b5b4-62f0a83e991a", "type": "concept", "title": "Decision owner, user of research, budget, risk tolerance, market context, and competitive pressure"}, {"id": "15e7c30c-e1e4-4e64-91d9-cdf28599093a", "type": "concept", "title": "Pre-read alignment, assumption mapping, and project kickoff"}, {"id": "330bf677-a585-4cf4-b660-e14b70fb86d0", "type": "concept", "title": "Avoiding scope creep and post-hoc reinterpretation"}], "description": "Research becomes more valuable when stakeholders agree on the decision, audience, and action threshold."}]}, {"id": "ff79b6e0-fccc-40b1-8afc-6f18e61a6b03", "type": "topic", "title": "Research Design, Mixed Methods, and Evidence Planning", "description": "Choose exploratory, descriptive, causal, qualitative, quantitative, and mixed-method designs that fit the business decision.", "children": [{"id": "d4005ba1-6c97-463a-b3e5-fabc00262bae", "type": "subtopic", "title": "Exploratory, Descriptive, and Causal Designs", "children": [{"id": "6a3dc280-8f63-445f-a577-3e1e283f3b0e", "type": "concept", "title": "Exploratory discovery, descriptive measurement, causal testing, tracking, and diagnostic research"}, {"id": "5d4b3ece-2bca-4976-9f70-1a196eac9b93", "type": "concept", "title": "Qualitative, quantitative, observational, experimental, and mixed-method designs"}, {"id": "b6fdc6cf-e629-4043-bb83-8876f02ea73d", "type": "concept", "title": "Research design as evidence architecture"}], "description": "Students learn to match method to question instead of defaulting to surveys."}, {"id": "054cb5d2-4ac2-4eaf-9bc8-1c11d674024f", "type": "subtopic", "title": "Mixed-Methods Sequencing", "children": [{"id": "6b1e90f6-22cc-40f0-807c-57f62d49f885", "type": "concept", "title": "Qual-to-quant, quant-to-qual, triangulation, explanatory design, and iterative design"}, {"id": "32816bc4-b64f-4003-81e0-05041661b7a0", "type": "concept", "title": "Discovery interviews before survey design, segmentation followed by profiling, and experiments after concept screening"}, {"id": "4108c1a9-0a91-4e01-87a6-4bf1d1fb4aad", "type": "concept", "title": "Integration of findings across methods"}], "description": "Combining methods works best when each phase has a clear purpose."}, {"id": "b284a4b0-8454-4a5e-acf8-86ebbf5c8808", "type": "subtopic", "title": "Evidence Plan and Research Roadmap", "children": [{"id": "139cf464-a577-4b21-89d5-85e3a1fcea00", "type": "concept", "title": "Research matrix, data sources, recruitment plan, timeline, budget, quality checks, and analysis plan"}, {"id": "1bf9c984-6a63-4458-902d-184fac6aedf8", "type": "concept", "title": "Minimum viable research versus comprehensive programs"}, {"id": "704ad3d3-938b-4a2a-9539-125eacaa40c7", "type": "concept", "title": "Tradeoffs among rigor, speed, cost, and confidence"}], "description": "An evidence plan links method, sample, instrument, analysis, and deliverable to the decision."}]}, {"id": "31add8fb-2fd1-4d85-8206-02f79bc7673a", "type": "topic", "title": "Secondary Data, Market Intelligence, and Digital Trace Data", "description": "Use existing data responsibly before commissioning primary research, including market reports, census data, search data, CRM data, and platform analytics.", "children": [{"id": "46e93039-cfac-4494-9245-1e1d77c1dc8c", "type": "subtopic", "title": "Secondary Data Audit", "children": [{"id": "ba696ffc-6e1a-4caf-9bd4-f8ccc1b25dfe", "type": "concept", "title": "Internal records, CRM, sales data, web analytics, syndicated reports, government data, and competitor materials"}, {"id": "742e133b-3d75-4e09-921e-b172d8ac6bf7", "type": "concept", "title": "Source credibility, recency, coverage, definitions, and comparability"}, {"id": "265eee80-3045-48a2-8d38-d4c313813f20", "type": "concept", "title": "Desk research workflow and citation discipline"}], "description": "Secondary research prevents wasted effort and helps students understand market context before primary research."}, {"id": "82aa9afe-d2e2-4bfb-8b40-ab9fb50608d2", "type": "subtopic", "title": "Market and Competitive Intelligence", "children": [{"id": "81640eac-20d2-4c4f-bc7c-0c017cc47e73", "type": "concept", "title": "Market size, growth, share, category structure, competitor positioning, pricing, channels, and substitutes"}, {"id": "60f0f11a-009e-436f-9cf5-1243ba749602", "type": "concept", "title": "PESTEL, Porter's forces, category entry points, and trend analysis"}, {"id": "9f6bb09b-272e-4e52-be8d-17853a87178c", "type": "concept", "title": "Use and limits of public data and industry reports"}], "description": "Students learn to map markets, categories, competitors, and demand signals."}, {"id": "ca318737-5ab2-4f97-ba16-2dcef088f058", "type": "subtopic", "title": "Big Data and Behavioral Traces", "children": [{"id": "54bbaa42-223e-473d-8890-a2612fef9c47", "type": "concept", "title": "Search trends, social data, clickstream, transaction data, loyalty data, reviews, and app events"}, {"id": "76bb0d96-7392-4a32-840b-7aa9ea7219c5", "type": "concept", "title": "Data exhaust, selection bias, measurement gaps, and platform changes"}, {"id": "36866f64-a170-449a-9313-60135d75c3ef", "type": "concept", "title": "What behavior data can and cannot say about motives"}], "description": "Digital and operational data can reveal behavior at scale, but it requires careful interpretation."}]}, {"id": "c621c00e-4c5e-4285-b39e-dfeefbd5c632", "type": "topic", "title": "Qualitative Research: Interviews, Focus Groups, Ethnography, and Customer Discovery", "description": "Learn how qualitative research reveals motives, language, context, unmet needs, barriers, and opportunity spaces.", "children": [{"id": "1d32caf8-b7d5-4e16-82be-4b5df84c44fd", "type": "subtopic", "title": "Depth Interviews and Customer Discovery", "children": [{"id": "62aaacc2-ccd1-43fb-88e3-3a431744f82e", "type": "concept", "title": "Discussion guides, probes, laddering, jobs to be done, pain points, and unmet needs"}, {"id": "ceff3615-b794-4aa4-8529-6fcace9f29bd", "type": "concept", "title": "Recruiting, moderation, rapport, active listening, and note-taking"}, {"id": "d7e05d7a-bee2-474f-a7d2-71db2725c832", "type": "concept", "title": "Synthesis from transcripts, quotes, patterns, and contradictions"}], "description": "Interviews help researchers understand language, motivations, needs, barriers, and decision journeys."}, {"id": "6aa94060-240f-406a-9b26-275adfd92093", "type": "subtopic", "title": "Focus Groups and Co-Creation", "children": [{"id": "136862c4-0173-4d71-92ae-579b39e183db", "type": "concept", "title": "Focus groups, mini-groups, online communities, workshops, concept boards, and stimulus testing"}, {"id": "703e4580-78d1-49d8-917d-f234325e2b66", "type": "concept", "title": "Group dynamics, dominance, conformity, moderation, and projective techniques"}, {"id": "0261b81f-2cc7-4d18-938d-cb093df68a07", "type": "concept", "title": "When focus groups are useful and when they mislead"}], "description": "Group methods can reveal social meaning, concept reactions, vocabulary, and creative possibilities when used carefully."}, {"id": "73246740-26f9-4bbd-97b6-d19d372c932f", "type": "subtopic", "title": "Ethnography and Contextual Observation", "children": [{"id": "1eb3a035-dd80-4650-9c31-4d921b9cd435", "type": "concept", "title": "Shop-alongs, diary studies, contextual inquiry, mobile ethnography, user observation, and service safaris"}, {"id": "1178f86b-8a53-4f12-8615-db3baefbd0a1", "type": "concept", "title": "Environment, routines, workarounds, artifacts, and embodied behavior"}, {"id": "38eb334a-6632-4d58-a69f-b384abc32a8d", "type": "concept", "title": "Ethics of observation and interpretation"}], "description": "Observational research helps students see the gap between what people say and what people do."}]}, {"id": "db31345d-7b1e-4233-a169-1b3dc68fc22d", "type": "topic", "title": "Survey Design, Questionnaire Craft, and Measurement Validity", "description": "Build surveys that measure the right constructs with clear wording, valid scales, and minimized response bias.", "children": [{"id": "13a53266-627e-4bd4-adcf-14898e749f54", "type": "subtopic", "title": "Constructs and Measures", "children": [{"id": "2d524bdf-e920-470b-8328-75589fc6446c", "type": "concept", "title": "Constructs, operationalization, indicators, latent variables, and measurement model"}, {"id": "616d374d-5977-4e47-99c1-2f730a0c82c2", "type": "concept", "title": "Awareness, attitudes, preferences, satisfaction, loyalty, intent, usage, and willingness to pay"}, {"id": "c232ad9c-6e72-490d-aa07-887f5fb6bb8e", "type": "concept", "title": "Validity, reliability, sensitivity, and benchmark comparability"}], "description": "Strong surveys begin by defining what needs to be measured before writing questions."}, {"id": "a48e8fbf-e7e9-4fb7-8b03-7be79c6954c2", "type": "subtopic", "title": "Questionnaire Writing", "children": [{"id": "4aac95f8-9633-4374-b955-fa53c3b7ec6c", "type": "concept", "title": "Question order, screening, branching, scale labels, recall periods, neutral wording, and response options"}, {"id": "fc048450-febf-4eca-8ba0-fdd5ac360825", "type": "concept", "title": "Leading, loaded, double-barreled, ambiguous, and socially desirable questions"}, {"id": "2e26d790-4635-49ce-9789-c97880f75971", "type": "concept", "title": "Pretesting, cognitive interviews, and survey pilots"}], "description": "Question wording can quietly determine the quality of the entire study."}, {"id": "abd30276-52c3-4b52-ae03-2adad4b77ecf", "type": "subtopic", "title": "Scale Design and Survey Experience", "children": [{"id": "fdfe966c-64d9-4319-9075-a1b652951970", "type": "concept", "title": "Likert scales, semantic differential scales, ranking, max-diff, constant sum, open text, and matrix questions"}, {"id": "04354b71-efc8-4852-9ab4-1ded44ae9324", "type": "concept", "title": "Mobile-first design, survey fatigue, length, incentives, and accessibility"}, {"id": "b7dc1671-7980-4d14-88a8-80dea198b015", "type": "concept", "title": "Translation, localization, and cross-cultural measurement"}], "description": "Students learn to design surveys respondents can answer accurately and willingly."}]}, {"id": "f37ddd65-d5db-441c-8d49-f021846aac24", "type": "topic", "title": "Sampling, Panels, Fieldwork, and Data Quality", "description": "Design samples and fieldwork protocols that produce credible, transparent, and decision-useful evidence.", "children": [{"id": "a9b51646-760c-42b5-94ee-16743470ccac", "type": "subtopic", "title": "Sampling Logic", "children": [{"id": "c8000b1e-64db-4fe3-ae42-fc54bae9df98", "type": "concept", "title": "Population, sampling frame, census, probability sampling, nonprobability sampling, and sample size"}, {"id": "dc7b2971-1480-4805-9ce1-9df36fadddf1", "type": "concept", "title": "Simple random, stratified, cluster, quota, convenience, snowball, and purposive sampling"}, {"id": "0ed5bf94-c8ce-4749-8671-a2910145242e", "type": "concept", "title": "Margin of error, confidence interval, incidence rate, and feasibility"}], "description": "Sampling determines how confidently findings can speak beyond the people observed."}, {"id": "5afe9352-96b6-4814-8175-1f6f258007ae", "type": "subtopic", "title": "Panels and Fieldwork Operations", "children": [{"id": "bd124008-e770-442a-bd6c-0ef14d6fe186", "type": "concept", "title": "Online panels, customer lists, intercepts, B2B recruiting, hard-to-reach audiences, and incentives"}, {"id": "029b81fd-c5f7-42f5-9309-aaf98aa8e0d0", "type": "concept", "title": "Screeners, quotas, fieldwork monitoring, response rates, and vendor management"}, {"id": "4b590066-5b69-4a66-b77a-d9dc4db0199f", "type": "concept", "title": "Survey launch checklist and fieldwork troubleshooting"}], "description": "Students learn the practical mechanics of recruiting, screening, fielding, and monitoring research."}, {"id": "b0b47a72-a189-41b9-bcd7-a51e885ce588", "type": "subtopic", "title": "Data Quality and Cleaning", "children": [{"id": "01a7cb82-4c58-42b1-ba25-09d7c36d0a9f", "type": "concept", "title": "Speeders, straight-liners, duplicate responses, bot detection, attention checks, open-end quality, and missing data"}, {"id": "af882444-4b0d-41d4-9bac-58edfa12e84f", "type": "concept", "title": "Weighting, outlier handling, data cleaning logs, and transparency"}, {"id": "4a8d198a-6607-4fd0-af19-8d9f633e94a2", "type": "concept", "title": "Bias from poor recruitment, bad instruments, and careless fielding"}], "description": "Good analysis starts with knowing which responses deserve trust."}]}, {"id": "b1e21dd7-e71c-4d6b-af18-ceab7fe54d82", "type": "topic", "title": "Experiments, A/B Testing, Concept Testing, and Causal Evidence", "description": "Use experimental logic to evaluate claims about products, messages, prices, user experiences, and campaigns.", "children": [{"id": "88abb65a-73da-4c19-872e-ee29b61774ed", "type": "subtopic", "title": "Experimental Logic", "children": [{"id": "7f184947-c18b-47dd-8fa6-e3ad32e8f57d", "type": "concept", "title": "Treatment, control, random assignment, manipulation, dependent variable, confounds, and internal validity"}, {"id": "77f39642-a9af-4530-89ee-f195bd843b8b", "type": "concept", "title": "Laboratory, field, online, and natural experiments"}, {"id": "0eda1fc3-6737-4810-9949-b3550fffcc83", "type": "concept", "title": "Effect size, statistical power, and practical significance"}], "description": "Experiments help marketers learn what causes outcomes rather than merely what correlates with them."}, {"id": "2f791609-1c70-434c-a47e-bdfbb6ca42b9", "type": "subtopic", "title": "A/B Testing and Digital Experiments", "children": [{"id": "496de150-fe6b-4698-8c1c-db57cac96c6a", "type": "concept", "title": "Hypothesis, variants, traffic allocation, guardrail metrics, conversion metrics, and stopping rules"}, {"id": "343c5392-06a6-4542-9793-8a5201eebc82", "type": "concept", "title": "Sample ratio mismatch, novelty effects, peeking, multiple comparisons, and interference"}, {"id": "9fc515d0-1353-42d1-84fd-405dda58bf84", "type": "concept", "title": "Experiment documentation and learning repositories"}], "description": "A/B testing brings experimental thinking into websites, apps, emails, ads, and funnels."}, {"id": "529abfbc-24e6-4725-88f4-42899d20c6c9", "type": "subtopic", "title": "Concept, Product, and Message Testing", "children": [{"id": "aa3ee6b7-342d-48f7-928e-79182923e4b5", "type": "concept", "title": "Concept tests, monadic designs, sequential monadic designs, message tests, package tests, and ad copy tests"}, {"id": "f918868d-86ae-46d9-b63b-145a8c1b26ef", "type": "concept", "title": "Test stimuli, benchmarks, normative databases, and decision thresholds"}, {"id": "993ef130-b564-4f7e-bcfc-2846486cd2aa", "type": "concept", "title": "Connecting test results to launch, iteration, or kill decisions"}], "description": "Students apply causal and quasi-causal designs to marketing decisions."}]}, {"id": "e21cd4d1-92c6-4082-a149-4b7d7d6a987e", "type": "topic", "title": "Quantitative Analysis: Descriptives, Inference, Regression, and Modeling Basics", "description": "Analyze research data with statistical discipline, connecting findings to uncertainty, effect size, and managerial meaning.", "children": [{"id": "08f9ba04-aa70-46e6-9046-6b6b78af829e", "type": "subtopic", "title": "Descriptive Analysis and Cross-Tabs", "children": [{"id": "bacfec4a-1ccd-440e-a948-d62dd242626c", "type": "concept", "title": "Frequencies, means, medians, distributions, cross-tabs, top-box scores, nets, and subgroup comparisons"}, {"id": "86d75eb1-c975-44cf-ade5-3dbe0bd3e653", "type": "concept", "title": "Weighting, filters, missing data, and base sizes"}, {"id": "81823db1-d90c-4fca-9ccb-299d4937e6a2", "type": "concept", "title": "Avoiding misleading percentages and overclaiming small cells"}], "description": "Descriptive analysis turns raw responses into readable patterns and initial implications."}, {"id": "ddea99ec-c3b6-4cfa-bd36-525dbd50fd9f", "type": "subtopic", "title": "Statistical Inference", "children": [{"id": "ede6e9b1-bb6c-47e9-8875-f1de92af893e", "type": "concept", "title": "Confidence intervals, hypothesis tests, p-values, effect sizes, chi-square, t-tests, ANOVA, and nonparametric checks"}, {"id": "f52469ae-fe53-413e-9ca1-4d4f498c232c", "type": "concept", "title": "Statistical significance versus managerial significance"}, {"id": "cdc501af-cc9d-4794-ab0b-c93185022866", "type": "concept", "title": "Multiple testing and false certainty"}], "description": "Students learn how to distinguish signal from noise without turning statistics into decoration."}, {"id": "2c26529d-738d-4ae4-93e2-d97b77ec4a1a", "type": "subtopic", "title": "Regression and Predictive Modeling Basics", "children": [{"id": "0280e3ef-39c0-48c6-ad0e-acc59566721b", "type": "concept", "title": "Correlation, regression, logistic regression, classification, validation, overfitting, and feature selection"}, {"id": "dc702322-3134-4b68-9658-d780ccf02fcc", "type": "concept", "title": "Drivers of satisfaction, purchase intent, churn, and response"}, {"id": "287e0c99-754b-48f5-a55a-0d2ceeba48d3", "type": "concept", "title": "Model interpretation for nontechnical decision-makers"}], "description": "Modeling helps explain drivers and predict outcomes, but only if assumptions and limitations are visible."}]}, {"id": "602dd5b4-02ce-45c5-b732-81f1a6ab3914", "type": "topic", "title": "Segmentation, Targeting Insights, Personas, and Customer Heterogeneity", "description": "Turn research data into meaningful customer groups, needs states, jobs to be done, and targeting implications.", "children": [{"id": "302a8b4a-260a-4fad-bdd8-e9e20b1b93d4", "type": "subtopic", "title": "Segmentation Strategy", "children": [{"id": "0a498e01-e04b-434a-aeab-673d35b5b600", "type": "concept", "title": "Needs-based, behavioral, psychographic, demographic, firmographic, and value-based segmentation"}, {"id": "c7ff881f-a201-4ecd-8581-26951736320b", "type": "concept", "title": "Actionability, identifiability, accessibility, responsiveness, and profitability"}, {"id": "759f13d1-f8ef-4544-a235-1944b9a0aeb0", "type": "concept", "title": "Segment sizing and prioritization"}], "description": "Segmentation is useful when it changes targeting, positioning, product, or resource allocation decisions."}, {"id": "f051eee9-e21c-4f60-8121-ce33b73ca06b", "type": "subtopic", "title": "Segmentation Methods", "children": [{"id": "dc7d4f60-d32e-424a-af0d-5bd47e179a85", "type": "concept", "title": "Cluster analysis, latent class analysis, factor analysis, decision trees, and rule-based segmentation"}, {"id": "f177d9bc-ce08-484c-a81c-91ff0a9b55ee", "type": "concept", "title": "Variable selection, standardization, number of segments, profiling, and validation"}, {"id": "7f65fe27-6b8d-4b24-9637-9c873155384b", "type": "concept", "title": "Interpreting segments without stereotyping customers"}], "description": "Students learn the analytical approaches behind customer grouping."}, {"id": "85057f17-5370-4c26-b198-5fd3dca09205", "type": "subtopic", "title": "Personas and Jobs to Be Done", "children": [{"id": "7171d567-7442-41b4-abd6-ddc8410d73a6", "type": "concept", "title": "Persona evidence, customer jobs, outcomes, pains, gains, trigger events, and usage occasions"}, {"id": "ebc274f2-fa3c-495c-ab52-c3e52db21a1c", "type": "concept", "title": "Difference between creative persona, evidence-based persona, and stereotype"}, {"id": "ec79dcb0-9420-4830-9330-f4253d151acd", "type": "concept", "title": "Using personas in positioning, messaging, and journey design"}], "description": "Personas and jobs frameworks translate data into empathy and product/communication decisions."}]}, {"id": "38836dc2-17a3-4bf4-abfc-deef32b15d76", "type": "topic", "title": "Brand, Product, Pricing, and Customer Value Research", "description": "Apply research methods to brand equity, product-market fit, willingness to pay, conjoint analysis, satisfaction, loyalty, and customer value.", "children": [{"id": "e50fcd69-1132-463f-bcc6-0bab67c2bc3f", "type": "subtopic", "title": "Brand and Positioning Research", "children": [{"id": "f0341de6-1a41-42fc-9612-a82272273fc1", "type": "concept", "title": "Awareness, recall, recognition, brand associations, equity, consideration, preference, and distinctiveness"}, {"id": "f97bb9f3-ef5a-4f4f-a5fa-b0d938873626", "type": "concept", "title": "Perceptual maps, brand trackers, copy tests, and positioning studies"}, {"id": "6431c75d-94cd-416d-ab3b-250616434cc6", "type": "concept", "title": "Competitive frames of reference and points of difference"}], "description": "Brand research measures what customers know, feel, remember, and associate with a brand."}, {"id": "b4a47d34-f8d9-40fa-b36a-381cdf239fa1", "type": "subtopic", "title": "Product and Innovation Research", "children": [{"id": "677855b3-f676-4b26-a54a-02c74027e035", "type": "concept", "title": "Concept testing, prototype testing, usability feedback, product-market fit, feature prioritization, and needs analysis"}, {"id": "821662df-042f-4f15-847e-d6d55ea33950", "type": "concept", "title": "Kano, max-diff, conjoint, choice modeling, and concept screening"}, {"id": "e1fcdc1e-608c-40e9-a13a-1822178f980a", "type": "concept", "title": "Translating feedback into product requirements"}], "description": "Product research helps teams decide what to build, improve, launch, or stop."}, {"id": "ae9361e4-eb31-4611-b21c-954d150da0b2", "type": "subtopic", "title": "Pricing and Customer Value", "children": [{"id": "2a50bb9b-75b4-4d29-b7b6-0a7334b63af6", "type": "concept", "title": "Van Westendorp, Gabor-Granger, conjoint, price elasticity, reference price, and value drivers"}, {"id": "ddc38146-9a8c-4542-93b4-8157345d190d", "type": "concept", "title": "Customer lifetime value, retention, loyalty, and customer equity"}, {"id": "901a3d0b-779b-4c2e-b3aa-3c9b5d5b88dd", "type": "concept", "title": "Limits of stated willingness to pay"}], "description": "Pricing research estimates willingness to pay and value perception while respecting strategic context."}]}, {"id": "838c3e8c-7f47-496a-a953-4bfdfd216f43", "type": "topic", "title": "Digital, Social, Search, and Behavioral Data Research", "description": "Integrate surveys and qualitative insight with digital behavior, social listening, analytics, attribution, and customer journey evidence.", "children": [{"id": "2e46b9a5-7092-4dad-8125-4f3b0da80fac", "type": "subtopic", "title": "Web and Product Analytics", "children": [{"id": "1c4a775c-975c-4691-b4d7-949c80488ac5", "type": "concept", "title": "GA4, events, funnels, cohorts, attribution, dashboards, tags, and conversion tracking"}, {"id": "371e03f1-e5cd-45eb-9ec1-e00d30f4b224", "type": "concept", "title": "Measurement plans, implementation QA, and channel taxonomy"}, {"id": "49e1bd82-ebc9-491b-b6fa-0ef8a733ae5c", "type": "concept", "title": "Behavioral metrics versus customer insight"}], "description": "Digital analytics provide behavioral evidence about acquisition, engagement, conversion, and retention."}, {"id": "54ca6879-03bc-4b2d-97f9-1c7cc3bb12d4", "type": "subtopic", "title": "Social Listening and Review Mining", "children": [{"id": "d0902cd0-2cb6-41ea-a1cd-7ca3312fd9c9", "type": "concept", "title": "Sentiment analysis, topic modeling, text coding, share of voice, influencer mapping, and review analysis"}, {"id": "b64b59bc-d6aa-4879-a12f-5fd65e4e4a04", "type": "concept", "title": "Sampling bias, sarcasm, bots, platform demographics, and context collapse"}, {"id": "a266670e-f2f3-4595-9c70-6646a607f340", "type": "concept", "title": "Turning unstructured text into research evidence"}], "description": "Social and review data reveal public language, complaints, advocacy, and emerging issues."}, {"id": "a9cb47fd-b5f7-4864-994a-1031555471a9", "type": "subtopic", "title": "Search and Demand Signals", "children": [{"id": "28929000-9d77-4d1c-af73-80ae242fc5a4", "type": "concept", "title": "Google Trends, keyword research, search intent, seasonality, content gaps, and competitive demand"}, {"id": "b9436a25-48ca-4e54-8e8a-362a860f5725", "type": "concept", "title": "Demand sensing, category language, and early trend detection"}, {"id": "f0e88bd9-5d93-4090-8f47-cac0cb71230d", "type": "concept", "title": "Triangulating search with surveys, sales, and qualitative research"}], "description": "Search data can reveal needs, language, timing, and category demand."}]}, {"id": "329169ce-fdff-4909-90cc-20946a21ff93", "type": "topic", "title": "Ethics, Privacy, Bias, Inclusion, and Responsible Insights", "description": "Practice marketing research that respects respondents, protects data, avoids manipulation, and recognizes bias in methods and interpretation.", "children": [{"id": "6b90bc10-950d-4a66-836e-eb60ab264216", "type": "subtopic", "title": "Research Ethics and Respondent Respect", "children": [{"id": "68040e1c-8623-4709-9cac-77afd0616a21", "type": "concept", "title": "Informed consent, voluntary participation, deception, incentives, vulnerable populations, and debriefing"}, {"id": "cc86ee6f-8048-48f1-b9ce-e44692ce29a2", "type": "concept", "title": "Confidentiality, anonymity, respondent burden, and right to withdraw"}, {"id": "15999026-b099-4d49-9018-ef35bdf2b318", "type": "concept", "title": "Professional codes and review practices"}], "description": "Ethical research protects people from harm and treats participation as a relationship of trust."}, {"id": "47b82c3f-48cd-4464-bd51-dd6f58452c9e", "type": "subtopic", "title": "Privacy, Security, and Data Governance", "children": [{"id": "3d5696b5-0ac7-45b4-bd17-4b40b8ede5b5", "type": "concept", "title": "Personally identifiable information, consent, data minimization, retention, access control, and secure transfer"}, {"id": "dfcdbdea-997d-4b71-ad8c-3f4cab7bb521", "type": "concept", "title": "GDPR, CCPA/CPRA awareness, FTC guidance, and platform policy constraints"}, {"id": "81c51f48-5404-4b3e-a9d6-05e82e3d94d1", "type": "concept", "title": "Privacy-by-design and responsible data sharing"}], "description": "Marketing research increasingly depends on customer data, so governance is part of the method."}, {"id": "d3723cc6-7882-4561-bb8b-95b70c02169b", "type": "subtopic", "title": "Bias, Inclusion, and Harm", "children": [{"id": "7ff6bdb3-e5f5-4ddc-a47e-9d38fe5039e3", "type": "concept", "title": "Coverage bias, nonresponse bias, algorithmic bias, stereotype threat, cultural bias, and accessibility"}, {"id": "e11cb508-7623-4194-ab9d-36577c3a7453", "type": "concept", "title": "Inclusive questionnaire design, multilingual research, and representative recruitment"}, {"id": "f7bd2f6b-cd54-43e7-b123-f98f15140698", "type": "concept", "title": "Avoiding manipulative targeting and harmful segmentation"}], "description": "Students learn to identify bias in sampling, measurement, analysis, and recommendations."}]}, {"id": "ea18acf7-9feb-40f5-89c9-d8c27f81b067", "type": "topic", "title": "Insight Reporting, Data Visualization, and Executive Storytelling", "description": "Transform analysis into clear recommendations, dashboards, narratives, and presentations that decision-makers can act on.", "children": [{"id": "deaeeb8a-8879-4241-8436-811c54a417ea", "type": "subtopic", "title": "From Findings to Insights", "children": [{"id": "c577292f-8062-415c-bee0-bc0c7899fb84", "type": "concept", "title": "Finding, implication, recommendation, evidence, confidence, and action"}, {"id": "fb8e1f50-375c-4099-bf5b-199f2119d8aa", "type": "concept", "title": "Insight hierarchy, executive summary, answer-first writing, and decision framing"}, {"id": "7cb0764e-4dbc-42e3-9ff2-0ac3301263c9", "type": "concept", "title": "Separating fact, interpretation, and recommendation"}], "description": "A finding states what happened; an insight explains why it matters and what to do next."}, {"id": "4bd0e634-9ee9-4944-a210-bcb1d688b697", "type": "subtopic", "title": "Visualization and Dashboard Design", "children": [{"id": "d58a83fe-a087-47b6-a0d9-bd17f161d751", "type": "concept", "title": "Charts, tables, cross-tabs, dashboards, scorecards, and data labels"}, {"id": "b2e92b05-4a8c-49ec-84de-ac957a915d1c", "type": "concept", "title": "Base sizes, uncertainty, scale choices, color, annotations, and accessibility"}, {"id": "b1a6916e-cbf1-4916-921f-ebf6fcd51c66", "type": "concept", "title": "Avoiding chartjunk, cherry-picking, and misleading comparisons"}], "description": "Research reporting should make patterns clear without distorting the evidence."}, {"id": "ad3f8493-fdad-40c5-97e7-346656b00b4d", "type": "subtopic", "title": "Presentation and Stakeholder Influence", "children": [{"id": "faf17168-8da6-4e53-b230-7c022bc191a8", "type": "concept", "title": "Storyline, audience analysis, recommendation logic, objections, and next steps"}, {"id": "75e0c804-227a-4ed1-a07f-08617c7f14f6", "type": "concept", "title": "Research readout, workshop, executive deck, and appendix"}, {"id": "bd6ed192-d4eb-476d-9c59-a50aeac43ae7", "type": "concept", "title": "Communicating limitations without weakening credibility"}], "description": "Insights only matter when decision-makers understand, trust, and use them."}]}, {"id": "008c60cc-9f6e-4b86-bf3c-7462b5c29f47", "type": "topic", "title": "Capstone: End-to-End Marketing Research Project", "description": "Synthesize problem definition, design, data collection, analysis, ethics, and presentation in a complete research project.", "children": [{"id": "62e17d7d-7099-48f2-97ed-50d51e20cfe8", "type": "subtopic", "title": "Research Brief and Design", "children": [{"id": "4ad60895-4f90-49da-ae38-62e1fbedc969", "type": "concept", "title": "Problem statement, decision context, learning objectives, hypotheses, method, sample, and timeline"}, {"id": "c9967adc-fcec-4b9f-8e00-c88464a579ba", "type": "concept", "title": "Research brief, stakeholder alignment, and evidence plan"}, {"id": "0e756040-c6ee-42f4-8857-e0477bfc01ee", "type": "concept", "title": "Ethics and privacy review before data collection"}], "description": "The capstone begins with a realistic business decision and a defensible research design."}, {"id": "c78e4baa-b09e-4743-a1f3-afcff88eb892", "type": "subtopic", "title": "Data Collection and Analysis", "children": [{"id": "19d6769d-75b3-4c54-a366-4f7a595a812a", "type": "concept", "title": "Qualitative protocol, survey instrument, sampling plan, fieldwork monitoring, and cleaning"}, {"id": "de755922-ffc1-488d-ac7d-90fba52699de", "type": "concept", "title": "Cross-tabs, statistical tests, regression, segmentation, and qualitative coding"}, {"id": "90b63125-ab59-4f5c-bdd5-65db182d4982", "type": "concept", "title": "Triangulation across primary and secondary evidence"}], "description": "Students carry out the research with enough rigor to make the findings credible."}, {"id": "f777008a-bed2-4107-b3e1-28772d546c3e", "type": "subtopic", "title": "Final Insight Deliverable", "children": [{"id": "ee245d0b-cedc-488f-a18a-524043f8e3ed", "type": "concept", "title": "Executive deck, methodology appendix, dashboard or visuals, and recommendation memo"}, {"id": "1b6c776b-d9b8-41d5-87c0-a278aa877a03", "type": "concept", "title": "Confidence, limitations, risks, and decision implications"}, {"id": "bdb4edf8-914e-4d1a-bc26-07434db6c80d", "type": "concept", "title": "Peer review, presentation, revision, and archive of research assets"}], "description": "The final project should look and feel like work a strong insights team could present to leadership."}]}], "dbBacked": true}$mkrsjson$::jsonb,
