insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('41c4f666-4e39-44ca-932d-eb12d496ec8c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Marketing Research, Insight Strategy, and Managerial Decision-Making', 'Frame marketing research as the disciplined process of reducing uncertainty for customer, market, brand, product, pricing, channel, and communication decisions.', 0),
  ('04fd8510-f93b-4bb6-b3a7-e24d26e2fca3', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '41c4f666-4e39-44ca-932d-eb12d496ec8c', 'subtopic'::public.curated_course_node_type, 'What Marketing Research Is For', 'Marketing research exists to improve decisions, not merely to collect opinions or produce reports.', 0),
  ('7d0df1c7-04a0-4c30-8be0-c6a6b2e8c54c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '04fd8510-f93b-4bb6-b3a7-e24d26e2fca3', 'concept'::public.curated_course_node_type, 'Decision uncertainty, customer insight, market opportunity, risk reduction, and evidence-based strategy', null, 0),
  ('cb55aad2-846c-49fc-8ab5-6df2ec902f6f', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '04fd8510-f93b-4bb6-b3a7-e24d26e2fca3', 'concept'::public.curated_course_node_type, 'Customer, competitor, brand, product, price, channel, communication, and experience decisions', null, 1),
  ('01846e87-b328-4009-adb2-3af901003562', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '04fd8510-f93b-4bb6-b3a7-e24d26e2fca3', 'concept'::public.curated_course_node_type, 'Difference between data, findings, insights, implications, and recommendations', null, 2),
  ('1f392d8d-a167-4e81-a42c-2fef0cbf587b', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '41c4f666-4e39-44ca-932d-eb12d496ec8c', 'subtopic'::public.curated_course_node_type, 'The Insight Function', 'Students learn how research teams operate inside firms, agencies, consultancies, startups, and product organizations.', 1),
  ('230060dd-8c25-4994-8319-dba7be7a8fc0', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1f392d8d-a167-4e81-a42c-2fef0cbf587b', 'concept'::public.curated_course_node_type, 'Client-side insights, agency research, UX research, analytics teams, marketing science, and customer experience', null, 0),
  ('2d8666e9-448d-4322-816c-db940d3aa23e', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1f392d8d-a167-4e81-a42c-2fef0cbf587b', 'concept'::public.curated_course_node_type, 'Stakeholders, briefs, budgets, timelines, vendors, panels, and research operations', null, 1),
  ('c0a5089e-0bd7-4ded-a482-9bc4749fb86b', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1f392d8d-a167-4e81-a42c-2fef0cbf587b', 'concept'::public.curated_course_node_type, 'How insights influence strategy, design, campaigns, and investment decisions', null, 2),
  ('bbf02f11-350f-4245-8db1-569a215a39f1', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '41c4f666-4e39-44ca-932d-eb12d496ec8c', 'subtopic'::public.curated_course_node_type, 'Research Quality and Decision Value', 'A world-class course teaches students to judge research by usefulness, credibility, ethics, and actionability.', 2),
  ('3d4b7ba4-09bd-4741-90e0-9e58258b20ba', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'bbf02f11-350f-4245-8db1-569a215a39f1', 'concept'::public.curated_course_node_type, 'Validity, reliability, representativeness, transparency, bias, triangulation, and reproducibility', null, 0),
  ('ad5efe31-6ba5-4831-8b73-2ad145cfc7a2', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'bbf02f11-350f-4245-8db1-569a215a39f1', 'concept'::public.curated_course_node_type, 'Decision value, opportunity cost, research risk, and speed versus rigor tradeoffs', null, 1),
  ('8fd7c738-88f9-4c8e-a831-79aa24ca0c12', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'bbf02f11-350f-4245-8db1-569a215a39f1', 'concept'::public.curated_course_node_type, 'When not to research and when existing evidence is enough', null, 2),
  ('28ed90d3-a1c5-4727-9eb4-ca4c07869679', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Problem Definition, Research Questions, and Decision Context', 'Translate vague business symptoms into decision-ready research problems, hypotheses, and actionable learning objectives.', 1),
  ('2d27b2af-f4f1-4bbf-9dd9-aa3f2e0b823c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '28ed90d3-a1c5-4727-9eb4-ca4c07869679', 'subtopic'::public.curated_course_node_type, 'From Business Symptom to Research Problem', 'This subtopic trains students to resist solving the wrong problem beautifully.', 0),
  ('ab7a008c-8413-42fa-bbdc-5d602b6984bf', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2d27b2af-f4f1-4bbf-9dd9-aa3f2e0b823c', 'concept'::public.curated_course_node_type, 'Symptoms versus causes, management decision problem, marketing research problem, and information gaps', null, 0),
  ('9fd9f123-9fa9-42fe-bdd7-5e84d492f4db', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2d27b2af-f4f1-4bbf-9dd9-aa3f2e0b823c', 'concept'::public.curated_course_node_type, 'Stakeholder interviews, background analysis, assumptions, constraints, and decision timeline', null, 1),
  ('c0083a20-1523-443e-b98a-59cf5cb883ed', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2d27b2af-f4f1-4bbf-9dd9-aa3f2e0b823c', 'concept'::public.curated_course_node_type, 'Problem statements, objectives, hypotheses, and success criteria', null, 2),
  ('1575cba5-5337-46e3-91f7-86ea41b997db', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '28ed90d3-a1c5-4727-9eb4-ca4c07869679', 'subtopic'::public.curated_course_node_type, 'Research Questions and Learning Objectives', 'Good research questions define what must be learned before a decision can be made.', 1),
  ('2671c310-fa0b-468f-b35e-dbe040a0b5b9', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1575cba5-5337-46e3-91f7-86ea41b997db', 'concept'::public.curated_course_node_type, 'Exploratory, descriptive, diagnostic, predictive, and causal questions', null, 0),
  ('472ea99f-78fb-4f68-9108-1fcdc2cef408', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1575cba5-5337-46e3-91f7-86ea41b997db', 'concept'::public.curated_course_node_type, 'Primary and secondary questions, hypotheses, constructs, variables, and expected use of findings', null, 1),
  ('0c6e1e1c-e696-4bb6-bc94-0b27261435fb', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1575cba5-5337-46e3-91f7-86ea41b997db', 'concept'::public.curated_course_node_type, 'Research briefs, scope, deliverables, and decision rules', null, 2),
  ('b34cb679-dcb4-4c3e-bf3a-0b543dbd9f0a', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '28ed90d3-a1c5-4727-9eb4-ca4c07869679', 'subtopic'::public.curated_course_node_type, 'Decision Context and Stakeholder Alignment', 'Research becomes more valuable when stakeholders agree on the decision, audience, and action threshold.', 2),
  ('bebca43a-85ab-4b64-b5b4-62f0a83e991a', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b34cb679-dcb4-4c3e-bf3a-0b543dbd9f0a', 'concept'::public.curated_course_node_type, 'Decision owner, user of research, budget, risk tolerance, market context, and competitive pressure', null, 0),
  ('15e7c30c-e1e4-4e64-91d9-cdf28599093a', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b34cb679-dcb4-4c3e-bf3a-0b543dbd9f0a', 'concept'::public.curated_course_node_type, 'Pre-read alignment, assumption mapping, and project kickoff', null, 1),
  ('330bf677-a585-4cf4-b660-e14b70fb86d0', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b34cb679-dcb4-4c3e-bf3a-0b543dbd9f0a', 'concept'::public.curated_course_node_type, 'Avoiding scope creep and post-hoc reinterpretation', null, 2),
  ('ff79b6e0-fccc-40b1-8afc-6f18e61a6b03', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Research Design, Mixed Methods, and Evidence Planning', 'Choose exploratory, descriptive, causal, qualitative, quantitative, and mixed-method designs that fit the business decision.', 2),
  ('d4005ba1-6c97-463a-b3e5-fabc00262bae', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ff79b6e0-fccc-40b1-8afc-6f18e61a6b03', 'subtopic'::public.curated_course_node_type, 'Exploratory, Descriptive, and Causal Designs', 'Students learn to match method to question instead of defaulting to surveys.', 0),
  ('6a3dc280-8f63-445f-a577-3e1e283f3b0e', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'd4005ba1-6c97-463a-b3e5-fabc00262bae', 'concept'::public.curated_course_node_type, 'Exploratory discovery, descriptive measurement, causal testing, tracking, and diagnostic research', null, 0),
  ('5d4b3ece-2bca-4976-9f70-1a196eac9b93', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'd4005ba1-6c97-463a-b3e5-fabc00262bae', 'concept'::public.curated_course_node_type, 'Qualitative, quantitative, observational, experimental, and mixed-method designs', null, 1),
  ('b6fdc6cf-e629-4043-bb83-8876f02ea73d', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'd4005ba1-6c97-463a-b3e5-fabc00262bae', 'concept'::public.curated_course_node_type, 'Research design as evidence architecture', null, 2),
  ('054cb5d2-4ac2-4eaf-9bc8-1c11d674024f', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ff79b6e0-fccc-40b1-8afc-6f18e61a6b03', 'subtopic'::public.curated_course_node_type, 'Mixed-Methods Sequencing', 'Combining methods works best when each phase has a clear purpose.', 1),
  ('6b1e90f6-22cc-40f0-807c-57f62d49f885', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '054cb5d2-4ac2-4eaf-9bc8-1c11d674024f', 'concept'::public.curated_course_node_type, 'Qual-to-quant, quant-to-qual, triangulation, explanatory design, and iterative design', null, 0),
  ('32816bc4-b64f-4003-81e0-05041661b7a0', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '054cb5d2-4ac2-4eaf-9bc8-1c11d674024f', 'concept'::public.curated_course_node_type, 'Discovery interviews before survey design, segmentation followed by profiling, and experiments after concept screening', null, 1),
  ('4108c1a9-0a91-4e01-87a6-4bf1d1fb4aad', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '054cb5d2-4ac2-4eaf-9bc8-1c11d674024f', 'concept'::public.curated_course_node_type, 'Integration of findings across methods', null, 2),
  ('b284a4b0-8454-4a5e-acf8-86ebbf5c8808', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ff79b6e0-fccc-40b1-8afc-6f18e61a6b03', 'subtopic'::public.curated_course_node_type, 'Evidence Plan and Research Roadmap', 'An evidence plan links method, sample, instrument, analysis, and deliverable to the decision.', 2),
  ('139cf464-a577-4b21-89d5-85e3a1fcea00', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b284a4b0-8454-4a5e-acf8-86ebbf5c8808', 'concept'::public.curated_course_node_type, 'Research matrix, data sources, recruitment plan, timeline, budget, quality checks, and analysis plan', null, 0),
  ('1bf9c984-6a63-4458-902d-184fac6aedf8', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b284a4b0-8454-4a5e-acf8-86ebbf5c8808', 'concept'::public.curated_course_node_type, 'Minimum viable research versus comprehensive programs', null, 1),
  ('704ad3d3-938b-4a2a-9539-125eacaa40c7', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b284a4b0-8454-4a5e-acf8-86ebbf5c8808', 'concept'::public.curated_course_node_type, 'Tradeoffs among rigor, speed, cost, and confidence', null, 2),
  ('31add8fb-2fd1-4d85-8206-02f79bc7673a', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Secondary Data, Market Intelligence, and Digital Trace Data', 'Use existing data responsibly before commissioning primary research, including market reports, census data, search data, CRM data, and platform analytics.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('46e93039-cfac-4494-9245-1e1d77c1dc8c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '31add8fb-2fd1-4d85-8206-02f79bc7673a', 'subtopic'::public.curated_course_node_type, 'Secondary Data Audit', 'Secondary research prevents wasted effort and helps students understand market context before primary research.', 0),
  ('ba696ffc-6e1a-4caf-9bd4-f8ccc1b25dfe', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '46e93039-cfac-4494-9245-1e1d77c1dc8c', 'concept'::public.curated_course_node_type, 'Internal records, CRM, sales data, web analytics, syndicated reports, government data, and competitor materials', null, 0),
  ('742e133b-3d75-4e09-921e-b172d8ac6bf7', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '46e93039-cfac-4494-9245-1e1d77c1dc8c', 'concept'::public.curated_course_node_type, 'Source credibility, recency, coverage, definitions, and comparability', null, 1),
