  ('82aa9afe-d2e2-4bfb-8b40-ab9fb50608d2', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '31add8fb-2fd1-4d85-8206-02f79bc7673a', 'subtopic'::public.curated_course_node_type, 'Market and Competitive Intelligence', 'Students learn to map markets, categories, competitors, and demand signals.', 1),
  ('81640eac-20d2-4c4f-bc7c-0c017cc47e73', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '82aa9afe-d2e2-4bfb-8b40-ab9fb50608d2', 'concept'::public.curated_course_node_type, 'Market size, growth, share, category structure, competitor positioning, pricing, channels, and substitutes', null, 0),
  ('60f0f11a-009e-436f-9cf5-1243ba749602', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '82aa9afe-d2e2-4bfb-8b40-ab9fb50608d2', 'concept'::public.curated_course_node_type, 'PESTEL, Porter''s forces, category entry points, and trend analysis', null, 1),
  ('9f6bb09b-272e-4e52-be8d-17853a87178c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '82aa9afe-d2e2-4bfb-8b40-ab9fb50608d2', 'concept'::public.curated_course_node_type, 'Use and limits of public data and industry reports', null, 2),
  ('ca318737-5ab2-4f97-ba16-2dcef088f058', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '31add8fb-2fd1-4d85-8206-02f79bc7673a', 'subtopic'::public.curated_course_node_type, 'Big Data and Behavioral Traces', 'Digital and operational data can reveal behavior at scale, but it requires careful interpretation.', 2),
  ('54bbaa42-223e-473d-8890-a2612fef9c47', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ca318737-5ab2-4f97-ba16-2dcef088f058', 'concept'::public.curated_course_node_type, 'Search trends, social data, clickstream, transaction data, loyalty data, reviews, and app events', null, 0),
  ('76bb0d96-7392-4a32-840b-7aa9ea7219c5', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ca318737-5ab2-4f97-ba16-2dcef088f058', 'concept'::public.curated_course_node_type, 'Data exhaust, selection bias, measurement gaps, and platform changes', null, 1),
  ('36866f64-a170-449a-9313-60135d75c3ef', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ca318737-5ab2-4f97-ba16-2dcef088f058', 'concept'::public.curated_course_node_type, 'What behavior data can and cannot say about motives', null, 2),
  ('c621c00e-4c5e-4285-b39e-dfeefbd5c632', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Qualitative Research: Interviews, Focus Groups, Ethnography, and Customer Discovery', 'Learn how qualitative research reveals motives, language, context, unmet needs, barriers, and opportunity spaces.', 4),
  ('1d32caf8-b7d5-4e16-82be-4b5df84c44fd', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'c621c00e-4c5e-4285-b39e-dfeefbd5c632', 'subtopic'::public.curated_course_node_type, 'Depth Interviews and Customer Discovery', 'Interviews help researchers understand language, motivations, needs, barriers, and decision journeys.', 0),
  ('62aaacc2-ccd1-43fb-88e3-3a431744f82e', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1d32caf8-b7d5-4e16-82be-4b5df84c44fd', 'concept'::public.curated_course_node_type, 'Discussion guides, probes, laddering, jobs to be done, pain points, and unmet needs', null, 0),
  ('ceff3615-b794-4aa4-8529-6fcace9f29bd', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1d32caf8-b7d5-4e16-82be-4b5df84c44fd', 'concept'::public.curated_course_node_type, 'Recruiting, moderation, rapport, active listening, and note-taking', null, 1),
  ('d7e05d7a-bee2-474f-a7d2-71db2725c832', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '1d32caf8-b7d5-4e16-82be-4b5df84c44fd', 'concept'::public.curated_course_node_type, 'Synthesis from transcripts, quotes, patterns, and contradictions', null, 2),
  ('6aa94060-240f-406a-9b26-275adfd92093', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'c621c00e-4c5e-4285-b39e-dfeefbd5c632', 'subtopic'::public.curated_course_node_type, 'Focus Groups and Co-Creation', 'Group methods can reveal social meaning, concept reactions, vocabulary, and creative possibilities when used carefully.', 1),
  ('136862c4-0173-4d71-92ae-579b39e183db', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '6aa94060-240f-406a-9b26-275adfd92093', 'concept'::public.curated_course_node_type, 'Focus groups, mini-groups, online communities, workshops, concept boards, and stimulus testing', null, 0),
  ('703e4580-78d1-49d8-917d-f234325e2b66', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '6aa94060-240f-406a-9b26-275adfd92093', 'concept'::public.curated_course_node_type, 'Group dynamics, dominance, conformity, moderation, and projective techniques', null, 1),
  ('0261b81f-2cc7-4d18-938d-cb093df68a07', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '6aa94060-240f-406a-9b26-275adfd92093', 'concept'::public.curated_course_node_type, 'When focus groups are useful and when they mislead', null, 2),
  ('73246740-26f9-4bbd-97b6-d19d372c932f', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'c621c00e-4c5e-4285-b39e-dfeefbd5c632', 'subtopic'::public.curated_course_node_type, 'Ethnography and Contextual Observation', 'Observational research helps students see the gap between what people say and what people do.', 2),
  ('1eb3a035-dd80-4650-9c31-4d921b9cd435', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '73246740-26f9-4bbd-97b6-d19d372c932f', 'concept'::public.curated_course_node_type, 'Shop-alongs, diary studies, contextual inquiry, mobile ethnography, user observation, and service safaris', null, 0),
  ('1178f86b-8a53-4f12-8615-db3baefbd0a1', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '73246740-26f9-4bbd-97b6-d19d372c932f', 'concept'::public.curated_course_node_type, 'Environment, routines, workarounds, artifacts, and embodied behavior', null, 1),
  ('38eb334a-6632-4d58-a69f-b384abc32a8d', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '73246740-26f9-4bbd-97b6-d19d372c932f', 'concept'::public.curated_course_node_type, 'Ethics of observation and interpretation', null, 2),
  ('db31345d-7b1e-4233-a169-1b3dc68fc22d', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Survey Design, Questionnaire Craft, and Measurement Validity', 'Build surveys that measure the right constructs with clear wording, valid scales, and minimized response bias.', 5),
  ('13a53266-627e-4bd4-adcf-14898e749f54', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'db31345d-7b1e-4233-a169-1b3dc68fc22d', 'subtopic'::public.curated_course_node_type, 'Constructs and Measures', 'Strong surveys begin by defining what needs to be measured before writing questions.', 0),
  ('2d524bdf-e920-470b-8328-75589fc6446c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '13a53266-627e-4bd4-adcf-14898e749f54', 'concept'::public.curated_course_node_type, 'Constructs, operationalization, indicators, latent variables, and measurement model', null, 0),
  ('616d374d-5977-4e47-99c1-2f730a0c82c2', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '13a53266-627e-4bd4-adcf-14898e749f54', 'concept'::public.curated_course_node_type, 'Awareness, attitudes, preferences, satisfaction, loyalty, intent, usage, and willingness to pay', null, 1),
  ('c232ad9c-6e72-490d-aa07-887f5fb6bb8e', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '13a53266-627e-4bd4-adcf-14898e749f54', 'concept'::public.curated_course_node_type, 'Validity, reliability, sensitivity, and benchmark comparability', null, 2),
  ('a48e8fbf-e7e9-4fb7-8b03-7be79c6954c2', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'db31345d-7b1e-4233-a169-1b3dc68fc22d', 'subtopic'::public.curated_course_node_type, 'Questionnaire Writing', 'Question wording can quietly determine the quality of the entire study.', 1),
  ('4aac95f8-9633-4374-b955-fa53c3b7ec6c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'a48e8fbf-e7e9-4fb7-8b03-7be79c6954c2', 'concept'::public.curated_course_node_type, 'Question order, screening, branching, scale labels, recall periods, neutral wording, and response options', null, 0),
  ('fc048450-febf-4eca-8ba0-fdd5ac360825', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'a48e8fbf-e7e9-4fb7-8b03-7be79c6954c2', 'concept'::public.curated_course_node_type, 'Leading, loaded, double-barreled, ambiguous, and socially desirable questions', null, 1),
  ('2e26d790-4635-49ce-9789-c97880f75971', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'a48e8fbf-e7e9-4fb7-8b03-7be79c6954c2', 'concept'::public.curated_course_node_type, 'Pretesting, cognitive interviews, and survey pilots', null, 2),
  ('abd30276-52c3-4b52-ae03-2adad4b77ecf', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'db31345d-7b1e-4233-a169-1b3dc68fc22d', 'subtopic'::public.curated_course_node_type, 'Scale Design and Survey Experience', 'Students learn to design surveys respondents can answer accurately and willingly.', 2),
  ('fdfe966c-64d9-4319-9075-a1b652951970', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'abd30276-52c3-4b52-ae03-2adad4b77ecf', 'concept'::public.curated_course_node_type, 'Likert scales, semantic differential scales, ranking, max-diff, constant sum, open text, and matrix questions', null, 0),
  ('04354b71-efc8-4852-9ab4-1ded44ae9324', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'abd30276-52c3-4b52-ae03-2adad4b77ecf', 'concept'::public.curated_course_node_type, 'Mobile-first design, survey fatigue, length, incentives, and accessibility', null, 1),
  ('b7dc1671-7980-4d14-88a8-80dea198b015', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'abd30276-52c3-4b52-ae03-2adad4b77ecf', 'concept'::public.curated_course_node_type, 'Translation, localization, and cross-cultural measurement', null, 2),
  ('f37ddd65-d5db-441c-8d49-f021846aac24', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Sampling, Panels, Fieldwork, and Data Quality', 'Design samples and fieldwork protocols that produce credible, transparent, and decision-useful evidence.', 6),
  ('a9b51646-760c-42b5-94ee-16743470ccac', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'f37ddd65-d5db-441c-8d49-f021846aac24', 'subtopic'::public.curated_course_node_type, 'Sampling Logic', 'Sampling determines how confidently findings can speak beyond the people observed.', 0);
