  ('01a7cb82-4c58-42b1-ba25-09d7c36d0a9f', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b0b47a72-a189-41b9-bcd7-a51e885ce588', 'concept'::public.curated_course_node_type, 'Speeders, straight-liners, duplicate responses, bot detection, attention checks, open-end quality, and missing data', null, 0),
