  ('4a8d198a-6607-4fd0-af19-8d9f633e94a2', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b0b47a72-a189-41b9-bcd7-a51e885ce588', 'concept'::public.curated_course_node_type, 'Bias from poor recruitment, bad instruments, and careless fielding', null, 2),
