  ('7f184947-c18b-47dd-8fa6-e3ad32e8f57d', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '88abb65a-73da-4c19-872e-ee29b61774ed', 'concept'::public.curated_course_node_type, 'Treatment, control, random assignment, manipulation, dependent variable, confounds, and internal validity', null, 0),
  ('77f39642-a9af-4530-89ee-f195bd843b8b', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '88abb65a-73da-4c19-872e-ee29b61774ed', 'concept'::public.curated_course_node_type, 'Laboratory, field, online, and natural experiments', null, 1),
  ('0eda1fc3-6737-4810-9949-b3550fffcc83', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '88abb65a-73da-4c19-872e-ee29b61774ed', 'concept'::public.curated_course_node_type, 'Effect size, statistical power, and practical significance', null, 2),
