  ('496de150-fe6b-4698-8c1c-db57cac96c6a', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2f791609-1c70-434c-a47e-bdfbb6ca42b9', 'concept'::public.curated_course_node_type, 'Hypothesis, variants, traffic allocation, guardrail metrics, conversion metrics, and stopping rules', null, 0),
