  ('aa3ee6b7-342d-48f7-928e-79182923e4b5', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '529abfbc-24e6-4725-88f4-42899d20c6c9', 'concept'::public.curated_course_node_type, 'Concept tests, monadic designs, sequential monadic designs, message tests, package tests, and ad copy tests', null, 0),
  ('f918868d-86ae-46d9-b63b-145a8c1b26ef', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '529abfbc-24e6-4725-88f4-42899d20c6c9', 'concept'::public.curated_course_node_type, 'Test stimuli, benchmarks, normative databases, and decision thresholds', null, 1),
