  ('86d75eb1-c975-44cf-ade5-3dbe0bd3e653', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '08f9ba04-aa70-46e6-9046-6b6b78af829e', 'concept'::public.curated_course_node_type, 'Weighting, filters, missing data, and base sizes', null, 1),
