  ('ede6e9b1-bb6c-47e9-8875-f1de92af893e', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ddea99ec-c3b6-4cfa-bd36-525dbd50fd9f', 'concept'::public.curated_course_node_type, 'Confidence intervals, hypothesis tests, p-values, effect sizes, chi-square, t-tests, ANOVA, and nonparametric checks', null, 0),
