  ('2c26529d-738d-4ae4-93e2-d97b77ec4a1a', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'e21cd4d1-92c6-4082-a149-4b7d7d6a987e', 'subtopic'::public.curated_course_node_type, 'Regression and Predictive Modeling Basics', 'Modeling helps explain drivers and predict outcomes, but only if assumptions and limitations are visible.', 2),
