  ('dc702322-3134-4b68-9658-d780ccf02fcc', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2c26529d-738d-4ae4-93e2-d97b77ec4a1a', 'concept'::public.curated_course_node_type, 'Drivers of satisfaction, purchase intent, churn, and response', null, 1),
