  ('f0341de6-1a41-42fc-9612-a82272273fc1', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'e50fcd69-1132-463f-bcc6-0bab67c2bc3f', 'concept'::public.curated_course_node_type, 'Awareness, recall, recognition, brand associations, equity, consideration, preference, and distinctiveness', null, 0),
  ('f97bb9f3-ef5a-4f4f-a5fa-b0d938873626', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'e50fcd69-1132-463f-bcc6-0bab67c2bc3f', 'concept'::public.curated_course_node_type, 'Perceptual maps, brand trackers, copy tests, and positioning studies', null, 1),
