  ('b4a47d34-f8d9-40fa-b36a-381cdf239fa1', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '38836dc2-17a3-4bf4-abfc-deef32b15d76', 'subtopic'::public.curated_course_node_type, 'Product and Innovation Research', 'Product research helps teams decide what to build, improve, launch, or stop.', 1),
  ('677855b3-f676-4b26-a54a-02c74027e035', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b4a47d34-f8d9-40fa-b36a-381cdf239fa1', 'concept'::public.curated_course_node_type, 'Concept testing, prototype testing, usability feedback, product-market fit, feature prioritization, and needs analysis', null, 0),
  ('821662df-042f-4f15-847e-d6d55ea33950', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b4a47d34-f8d9-40fa-b36a-381cdf239fa1', 'concept'::public.curated_course_node_type, 'Kano, max-diff, conjoint, choice modeling, and concept screening', null, 1),
  ('e1fcdc1e-608c-40e9-a13a-1822178f980a', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'b4a47d34-f8d9-40fa-b36a-381cdf239fa1', 'concept'::public.curated_course_node_type, 'Translating feedback into product requirements', null, 2),
  ('ae9361e4-eb31-4611-b21c-954d150da0b2', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '38836dc2-17a3-4bf4-abfc-deef32b15d76', 'subtopic'::public.curated_course_node_type, 'Pricing and Customer Value', 'Pricing research estimates willingness to pay and value perception while respecting strategic context.', 2),
  ('2a50bb9b-75b4-4d29-b7b6-0a7334b63af6', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ae9361e4-eb31-4611-b21c-954d150da0b2', 'concept'::public.curated_course_node_type, 'Van Westendorp, Gabor-Granger, conjoint, price elasticity, reference price, and value drivers', null, 0),
  ('ddc38146-9a8c-4542-93b4-8157345d190d', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ae9361e4-eb31-4611-b21c-954d150da0b2', 'concept'::public.curated_course_node_type, 'Customer lifetime value, retention, loyalty, and customer equity', null, 1),
  ('901a3d0b-779b-4c2e-b3aa-3c9b5d5b88dd', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ae9361e4-eb31-4611-b21c-954d150da0b2', 'concept'::public.curated_course_node_type, 'Limits of stated willingness to pay', null, 2),
