  ('2e46b9a5-7092-4dad-8125-4f3b0da80fac', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '838c3e8c-7f47-496a-a953-4bfdfd216f43', 'subtopic'::public.curated_course_node_type, 'Web and Product Analytics', 'Digital analytics provide behavioral evidence about acquisition, engagement, conversion, and retention.', 0),
  ('1c4a775c-975c-4691-b4d7-949c80488ac5', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2e46b9a5-7092-4dad-8125-4f3b0da80fac', 'concept'::public.curated_course_node_type, 'GA4, events, funnels, cohorts, attribution, dashboards, tags, and conversion tracking', null, 0),
  ('371e03f1-e5cd-45eb-9ec1-e00d30f4b224', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2e46b9a5-7092-4dad-8125-4f3b0da80fac', 'concept'::public.curated_course_node_type, 'Measurement plans, implementation QA, and channel taxonomy', null, 1),
  ('49e1bd82-ebc9-491b-b6fa-0ef8a733ae5c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '2e46b9a5-7092-4dad-8125-4f3b0da80fac', 'concept'::public.curated_course_node_type, 'Behavioral metrics versus customer insight', null, 2),
  ('54ca6879-03bc-4b2d-97f9-1c7cc3bb12d4', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '838c3e8c-7f47-496a-a953-4bfdfd216f43', 'subtopic'::public.curated_course_node_type, 'Social Listening and Review Mining', 'Social and review data reveal public language, complaints, advocacy, and emerging issues.', 1),
  ('d0902cd0-2cb6-41ea-a1cd-7ca3312fd9c9', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '54ca6879-03bc-4b2d-97f9-1c7cc3bb12d4', 'concept'::public.curated_course_node_type, 'Sentiment analysis, topic modeling, text coding, share of voice, influencer mapping, and review analysis', null, 0),
  ('b64b59bc-d6aa-4879-a12f-5fd65e4e4a04', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '54ca6879-03bc-4b2d-97f9-1c7cc3bb12d4', 'concept'::public.curated_course_node_type, 'Sampling bias, sarcasm, bots, platform demographics, and context collapse', null, 1),
  ('a266670e-f2f3-4595-9c70-6646a607f340', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '54ca6879-03bc-4b2d-97f9-1c7cc3bb12d4', 'concept'::public.curated_course_node_type, 'Turning unstructured text into research evidence', null, 2),
  ('a9cb47fd-b5f7-4864-994a-1031555471a9', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '838c3e8c-7f47-496a-a953-4bfdfd216f43', 'subtopic'::public.curated_course_node_type, 'Search and Demand Signals', 'Search data can reveal needs, language, timing, and category demand.', 2),
  ('28929000-9d77-4d1c-af73-80ae242fc5a4', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'a9cb47fd-b5f7-4864-994a-1031555471a9', 'concept'::public.curated_course_node_type, 'Google Trends, keyword research, search intent, seasonality, content gaps, and competitive demand', null, 0),
  ('b9436a25-48ca-4e54-8e8a-362a860f5725', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'a9cb47fd-b5f7-4864-994a-1031555471a9', 'concept'::public.curated_course_node_type, 'Demand sensing, category language, and early trend detection', null, 1),
  ('f0e88bd9-5d93-4090-8f47-cac0cb71230d', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'a9cb47fd-b5f7-4864-994a-1031555471a9', 'concept'::public.curated_course_node_type, 'Triangulating search with surveys, sales, and qualitative research', null, 2),
  ('329169ce-fdff-4909-90cc-20946a21ff93', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', null, 'topic'::public.curated_course_node_type, 'Ethics, Privacy, Bias, Inclusion, and Responsible Insights', 'Practice marketing research that respects respondents, protects data, avoids manipulation, and recognizes bias in methods and interpretation.', 12),
  ('6b90bc10-950d-4a66-836e-eb60ab264216', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '329169ce-fdff-4909-90cc-20946a21ff93', 'subtopic'::public.curated_course_node_type, 'Research Ethics and Respondent Respect', 'Ethical research protects people from harm and treats participation as a relationship of trust.', 0),
  ('68040e1c-8623-4709-9cac-77afd0616a21', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '6b90bc10-950d-4a66-836e-eb60ab264216', 'concept'::public.curated_course_node_type, 'Informed consent, voluntary participation, deception, incentives, vulnerable populations, and debriefing', null, 0),
  ('cc86ee6f-8048-48f1-b9ce-e44692ce29a2', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '6b90bc10-950d-4a66-836e-eb60ab264216', 'concept'::public.curated_course_node_type, 'Confidentiality, anonymity, respondent burden, and right to withdraw', null, 1);
