  ('15999026-b099-4d49-9018-ef35bdf2b318', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '6b90bc10-950d-4a66-836e-eb60ab264216', 'concept'::public.curated_course_node_type, 'Professional codes and review practices', null, 2),
