  ('81c51f48-5404-4b3e-a9d6-05e82e3d94d1', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '47b82c3f-48cd-4464-bd51-dd6f58452c9e', 'concept'::public.curated_course_node_type, 'Privacy-by-design and responsible data sharing', null, 2),
  ('d3723cc6-7882-4561-bb8b-95b70c02169b', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '329169ce-fdff-4909-90cc-20946a21ff93', 'subtopic'::public.curated_course_node_type, 'Bias, Inclusion, and Harm', 'Students learn to identify bias in sampling, measurement, analysis, and recommendations.', 2),
  ('7ff6bdb3-e5f5-4ddc-a47e-9d38fe5039e3', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'd3723cc6-7882-4561-bb8b-95b70c02169b', 'concept'::public.curated_course_node_type, 'Coverage bias, nonresponse bias, algorithmic bias, stereotype threat, cultural bias, and accessibility', null, 0),
  ('e11cb508-7623-4194-ab9d-36577c3a7453', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'd3723cc6-7882-4561-bb8b-95b70c02169b', 'concept'::public.curated_course_node_type, 'Inclusive questionnaire design, multilingual research, and representative recruitment', null, 1),
