  ('deaeeb8a-8879-4241-8436-811c54a417ea', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ea18acf7-9feb-40f5-89c9-d8c27f81b067', 'subtopic'::public.curated_course_node_type, 'From Findings to Insights', 'A finding states what happened; an insight explains why it matters and what to do next.', 0),
  ('c577292f-8062-415c-bee0-bc0c7899fb84', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'deaeeb8a-8879-4241-8436-811c54a417ea', 'concept'::public.curated_course_node_type, 'Finding, implication, recommendation, evidence, confidence, and action', null, 0),
  ('fb8e1f50-375c-4099-bf5b-199f2119d8aa', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'deaeeb8a-8879-4241-8436-811c54a417ea', 'concept'::public.curated_course_node_type, 'Insight hierarchy, executive summary, answer-first writing, and decision framing', null, 1),
  ('7cb0764e-4dbc-42e3-9ff2-0ac3301263c9', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'deaeeb8a-8879-4241-8436-811c54a417ea', 'concept'::public.curated_course_node_type, 'Separating fact, interpretation, and recommendation', null, 2),
  ('4bd0e634-9ee9-4944-a210-bcb1d688b697', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ea18acf7-9feb-40f5-89c9-d8c27f81b067', 'subtopic'::public.curated_course_node_type, 'Visualization and Dashboard Design', 'Research reporting should make patterns clear without distorting the evidence.', 1),
  ('d58a83fe-a087-47b6-a0d9-bd17f161d751', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '4bd0e634-9ee9-4944-a210-bcb1d688b697', 'concept'::public.curated_course_node_type, 'Charts, tables, cross-tabs, dashboards, scorecards, and data labels', null, 0),
  ('b2e92b05-4a8c-49ec-84de-ac957a915d1c', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '4bd0e634-9ee9-4944-a210-bcb1d688b697', 'concept'::public.curated_course_node_type, 'Base sizes, uncertainty, scale choices, color, annotations, and accessibility', null, 1),
  ('b1a6916e-cbf1-4916-921f-ebf6fcd51c66', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', '4bd0e634-9ee9-4944-a210-bcb1d688b697', 'concept'::public.curated_course_node_type, 'Avoiding chartjunk, cherry-picking, and misleading comparisons', null, 2),
