  ('faf17168-8da6-4e53-b230-7c022bc191a8', 'f7a8b9c0-1d2e-4f77-8a48-5b6c7d8e9f07', 'ad3f8493-fdad-40c5-97e7-346656b00b4d', 'concept'::public.curated_course_node_type, 'Storyline, audience analysis, recommendation logic, objections, and next steps', null, 0),
